import type { Tracker } from "@jini-ai/diagnostics/observability";
/** Tovu host binding for the single Jini lifecycle owner. Only ABI translation and product policy
 * live here; extraction, containment, trust, digest selection, activation and rollback stay in Jini.
 */
import path from "node:path";
import {
  createAgentPluginLifecycle,
  type AgentPluginLifecycleOptional,
  type AgentPluginArchiveEntry as JiniArchiveEntry,
  type AgentPluginArchiveReaderPort as JiniArchiveReader,
  type AgentPluginLayoutPort,
  type InstallAgentPluginRequired as JiniInstallRequired,
  type UninstallAgentPluginRequired as JiniUninstallRequired,
  type SeedBundledAgentPluginsRequired as JiniSeedRequired,
  type RetireBundledAgentPluginsRequired as JiniRetireRequired,
  type TrustedPluginPackagesQuery as JiniTrustedQuery,
  type TrustedPluginPackage,
  type InstalledAgentPlugin as JiniInstalledAgentPlugin,
  type AgentPluginDeliveryMode,
  type PluginContributionDefinition,
  type LoadPluginContributionsOptional,
  type FilesystemPort,
} from "@jini-ai/agent-plugins/lifecycle";
import { createNodeAgentPluginEffects } from "@jini-ai/agent-plugins/lifecycle/node";
import type { AgentPluginLayout, AgentPluginWorkspaceLayout } from "./layout.js";
import { migrateSiteAgentPluginLayouts } from "./memory.js";
import { carryCloudflareActivation } from "./deploy-split-activation.js";
import { UNTESTED_PLUGIN_GUIDANCE } from "./identity.js";
import { assertAgentPluginReady, findSoonAgentPlugin, readHostPluginMaturity, type SoonCatalogPort } from "./soon-lock.js";
import { readHostPluginRefOverlays, removeChatRefusedToolPermissions, splitHostPluginRefRequest, type HostPluginRefOptions } from "./host-plugin-guidance.js";
import { BUNDLED_AGENT_PLUGINS_SEEDED_ENABLED, RETIRED_BUNDLED_AGENT_PLUGINS, formatPluginToolPointer } from "./bundled-catalog.js";
import {
  readSupersessions, supersededDescriptorRefusal, supersededPackageRefusal, createBundledSourceManifestReader,
  type SupersessionManifestsPort,
} from "./supersession.js";

export {
  AgentPluginInstallError, AgentPluginNotFoundError, AgentPluginNotUninstallableError,
  AgentPluginChangedSincePreviewError, PackagePathViolation, BUNDLED_DIGESTS_FILENAME,
  defineExecutablePluginContribution, defineProviderContribution, contributeProviders,
} from "@jini-ai/agent-plugins/lifecycle";
export type {
  AgentPluginInstallErrorCode, InstalledAgentPluginSkill, InstalledAgentPlugin,
  InstallAgentPluginOptional, UninstallAgentPluginOptional, UninstallAgentPluginResult,
  AgentPluginUninstallPreview, StagedTree, SeededAgentPluginOutcome, SeedBundledAgentPluginsResult,
  RetiredAgentPluginOutcome, RetiredAgentPluginSuccessorOutcome, RetireBundledAgentPluginsOptional,
  BundledAgentPluginDigests, SeededBundledAgentPluginDigest, InstalledDigestIdentity,
  PackedAgentPluginArchive, AgentPluginSearchSkill, AgentPluginSearchCandidate, AgentPluginSearchMatch,
  TrustedPluginPackage, TrustedPluginVerdict, AgentPluginDeliveryMode, ResolveAgentPluginRefsResult,
  PluginContributionDefinition,
} from "@jini-ai/agent-plugins/lifecycle";
export { BUNDLED_AGENT_PLUGINS_SEEDED_ENABLED, RETIRED_BUNDLED_AGENT_PLUGINS } from "./bundled-catalog.js";

/** Compatibility with the host's positional archive ABI; the owner receives object arguments. */
export type AgentPluginArchiveEntry = Exclude<JiniArchiveEntry, { readonly kind: "file" }> |
  (Omit<Extract<JiniArchiveEntry, { readonly kind: "file" }>, "openReadStream"> & { readonly openReadStream: () => AsyncIterable<Uint8Array> });
/** Entries remain a pure function of archive bytes: metadata and extraction iterate twice. */
export interface AgentPluginArchiveReaderPort {
  entries(archive: Uint8Array): AsyncIterable<AgentPluginArchiveEntry>;
}
export type InstallAgentPluginRequired = Omit<JiniInstallRequired, "layout" | "archiveReader"> & { readonly layout: AgentPluginLayout; readonly archiveReader: AgentPluginArchiveReaderPort };
export type UninstallAgentPluginRequired = Omit<JiniUninstallRequired, "layout"> & { readonly layout: AgentPluginLayout };
export type SeedBundledAgentPluginsRequired = Omit<JiniSeedRequired, "layout"> & { readonly layout: AgentPluginLayout };
export type RetireBundledAgentPluginsRequired = Omit<JiniRetireRequired, "layout"> & { readonly layout: AgentPluginLayout };
export type TrustedPluginPackagesQuery = Omit<JiniTrustedQuery, "onInactive"> & { readonly onInactive?: (plugin: TrustedPluginPackage) => Promise<void> };

/** Preserve the host's validated workspace layout and convert only its method call shapes. */
function ownerLayout(layout: AgentPluginLayout): AgentPluginLayoutPort {
  return { root: layout.root, forWorkspace: ({ workspaceId }) => {
    const workspace = layout.forWorkspace(workspaceId);
    return { ...workspace, pluginDataDir: ({ pluginId }) => workspace.pluginDataDir(pluginId) };
  } };
}
function hostLayout(layout: AgentPluginLayoutPort): AgentPluginLayout {
  return { root: layout.root, workspacesDir: path.join(layout.root, "ws"), forWorkspace: workspaceId => {
    const workspace = layout.forWorkspace({ workspaceId });
    return { ...workspace, pluginDataDir: pluginId => workspace.pluginDataDir({ pluginId }) };
  } };
}
function ownerReader(reader: AgentPluginArchiveReaderPort): JiniArchiveReader {
  return { async *entries({ archive }) {
    for await (const entry of reader.entries(archive)) {
      yield entry.kind === "file" ? { ...entry, openReadStream: (_input = {}) => entry.openReadStream() } : entry;
    }
  } };
}

/** Reads the delivery mode for this process. An unset or unrecognised value is inject — an A/B
 * affordance must never change production behaviour by typo. */
export function resolveAgentPluginDeliveryMode(env: { readonly TOVU_AGENT_PLUGIN_DELIVERY?: string } = process.env): AgentPluginDeliveryMode {
  return env.TOVU_AGENT_PLUGIN_DELIVERY === "pointer" ? "pointer" : "inject";
}

// Preview and write paths reindex the same package; preserve its first diagnostic per process.
const reportedIdentityWarnings = new Set<string>();

/** Bind once per host; DI permits real-filesystem failure tests without replacing modules.
 * Network installation and MCP provisioning have separate host owners and are not used by this
 * binding. Refuse those unbound capabilities rather than bypassing their guards.
 * @complexity O(1) composition. All operations delegate to the lifecycle owner. */
export function createTovuAgentPluginLifecycle(required: { layout: AgentPluginLayout }, optional: { readonly bundledSourceRoot?: string; readonly productTracker?: () => Pick<Tracker, 'capture'>; readonly filesystem?: FilesystemPort; readonly identityAdmission?: AgentPluginLifecycleOptional["identityAdmission"]; readonly mcpProvisioning?: import("@jini-ai/agent-plugins/lifecycle").AgentPluginMcpProvisioningPort; readonly supersessionManifests?: SupersessionManifestsPort; readonly hostOverlaysDir?: string } = {}) {
  const unbound = async (): Promise<never> => { throw new Error("This lifecycle binding does not provide network installation or MCP provisioning"); };
  const policy: AgentPluginLifecycleOptional = {
    onActivationChanged: ({ pluginId, actor, enabled }) => optional.productTracker?.().capture({ name: enabled ? "agent_plugin_enabled" : "agent_plugin_disabled", userId: actor }, { properties: { pluginId, pluginKind: "agent", source: "shared" } }),
    ...(optional.identityAdmission ? { identityAdmission: optional.identityAdmission } : {}),
    onEvent: ({ event, message, pluginId }) => {
      if (event === 'agent-plugin-identity-warning' && pluginId !== undefined) {
        const key = JSON.stringify([pluginId, message]);
        if (reportedIdentityWarnings.has(key)) return;
        reportedIdentityWarnings.add(key);
      }
      console.warn(event.startsWith("migration") ? `[agent-plugins:${event}] ${message}` : message);
    },
    // Layout first, then preserve explicit Cloudflare rename decisions before seeding.
    // Hosting now seeds disabled; retirement still preserves an enabled deploy decision.
    // `owner` is bound below; this runs only at seed time, after it exists.
    migrateBeforeSeed: async ({ layout, workspaceId }) => {
      const migration = await migrateSiteAgentPluginLayouts({ contain: ({ root, entryPath }) => owner.assertContainedOnDisk({ packageRoot: root, entryPath }), layout: hostLayout(layout), workspaceId });
      if (migration.complete) {
        const required = { workspaceRoot: layout.forWorkspace({ workspaceId }).root, activations: owner };
        await carryCloudflareActivation(required);
      }
      return migration;
    },
    formatBundledUninstallRecovery: ({ pluginId }) => `used, disable it instead: call plugins_set_enabled with family 'agent-plugin', pluginId '${pluginId}', ` +
      "enabled false (disabling needs no confirmation), or turn it off from the Agent Plugins admin screen.",
  };
  const owner = createAgentPluginLifecycle({
    ...createNodeAgentPluginEffects({}, optional),
    // Boot chooses the site root before binding this owner; requests keep that same layout.
    layout: ownerLayout(required.layout),
    productName: "Tovu", extensionNamespace: "jini", bundledArchiveMagic: "TOVUPKG1\n",
    seededEnabledPluginIds: BUNDLED_AGENT_PLUGINS_SEEDED_ENABLED,
    retiredBundledPlugins: RETIRED_BUNDLED_AGENT_PLUGINS,
    deliveryMode: resolveAgentPluginDeliveryMode(), formatPluginToolPointer,
    fetch: unbound, outboundGuard: { assertAllowed: unbound },
    mcpProvisioning: optional.mcpProvisioning ?? { provision: unbound, setEnabled: unbound, remove: unbound, notifyRosterChanged: unbound },
  }, policy);
  const manifests: SupersessionManifestsPort = optional.supersessionManifests ?? {
    readInstalled: ({ plugin }) => owner.readTrustedPluginFile({ plugin, filename: "plugin.json" }),
    readBundledSource: optional.bundledSourceRoot === undefined ? unbound : createBundledSourceManifestReader({ bundledSourceRoot: optional.bundledSourceRoot }),
  };
  /** Apply host disclosure after Jini's trust/activation checks, for pinned and automatic guidance.
   * Order: maturity notices, each plugin's overlay `GUIDANCE.md` (`host-plugin-guidance.ts`; not in
   * pointer delivery, whose tool call carries it), the owner's sections, then a requested `host/`
   * file — the owner is asked without that file, which is Tovu's, not the plugin's.
   * @throws A manifest read failure; never deliver guidance while hiding its maturity.
   * @complexity One catalog scan plus one contained manifest read and one overlay read per selected plugin.
   */
  async function resolveHostPluginRefs(input: { pluginRefIds: readonly string[]; workspaceLayout: Pick<AgentPluginWorkspaceLayout, "packages" | "root"> }, options: HostPluginRefOptions = {}): Promise<import("@jini-ai/agent-plugins/lifecycle").ResolveAgentPluginRefsResult> {
    const request = splitHostPluginRefRequest({ options, defaultDeliveryMode: resolveAgentPluginDeliveryMode() });
    const result = await owner.resolveAgentPluginRefs(input, request.ownerOptions);
    if (!result.ok || input.pluginRefIds.length === 0) return result;
    const overlays = await readHostPluginRefOverlays({ pluginRefIds: input.pluginRefIds, ...request.overlay }, { overlaysDir: optional.hostOverlaysDir });
    if (!overlays.ok) return overlays;
    const installed = owner.preferBundledAgentPluginDigests({
      installed: await owner.listInstalledPlugins({ workspaceRoot: input.workspaceLayout.root }),
      bundled: await owner.readBundledAgentPluginDigests({ workspaceRoot: input.workspaceLayout.root }),
    });
    const selected = new Set(input.pluginRefIds);
    const notices = await Promise.all(installed.filter(plugin => selected.has(plugin.pluginId)).map(async plugin => {
      const manifest = JSON.parse(await owner.readTrustedPluginFile({ plugin, filename: "plugin.json" }));
      // Every maturity flag ("untested", "soon") means not tested end to end, so both carry the caution.
      return readHostPluginMaturity({ manifest, pluginId: plugin.pluginId }) ? `Plugin '${plugin.pluginId}' is untested. ${UNTESTED_PLUGIN_GUIDANCE}` : '';
    }));
    const promptPrefix = [...notices, ...overlays.guidance, result.promptPrefix, ...overlays.fileSections].filter(Boolean).join('\n\n');
    return { ...result, promptPrefix: removeChatRefusedToolPermissions(promptPrefix) };
  }
  // Soon plugins are locked off (`soon-lock.ts`, owner 2026-11-10). Product policy, so it wraps the
  // owner's enable writers here: the admin switch, plugins_set_enabled and connect defaults
  // (`setAgentPluginEnabled`) and the provider-face mirror (`reconcileAgentPluginActivation`). The raw
  // `setAgentPluginActivation` stays unwrapped: tests use it as a fixture and a backup import writes a
  // Soon plugin off itself (`site-backup/import-plugin-state.ts`); boot's lock catches anything else.
  // Turning OFF is never refused.
  const soonCatalog: SoonCatalogPort<JiniInstalledAgentPlugin> = {
    list: ({ workspaceRoot }) => owner.listInstalledPlugins({ workspaceRoot }),
    readManifest: ({ plugin }) => owner.readTrustedPluginFile({ plugin, filename: "plugin.json" }),
  };
  return {
    ...owner,
    soonCatalog,
    setAgentPluginEnabled: async (...[input, options]: Parameters<typeof owner.setAgentPluginEnabled>) => {
      if (input.enabled) await assertAgentPluginReady({ catalog: soonCatalog, workspaceRoot: required.layout.forWorkspace(input.workspaceId).root, pluginId: input.pluginId });
      return owner.setAgentPluginEnabled(input, options);
    },
    // A Soon face never follows its provider plugin on; one that is on is switched off.
    reconcileAgentPluginActivation: async (...[input, options]: Parameters<typeof owner.reconcileAgentPluginActivation>) => {
      const soon = await findSoonAgentPlugin({ catalog: soonCatalog, workspaceRoot: input.workspaceRoot, pluginId: input.pluginId });
      return owner.reconcileAgentPluginActivation(soon ? { ...input, resolveEnabled: async () => false } : input, options);
    },
    // Select the trusted replacement at the contribution owner BEFORE duplicate-id validation.
    // A failed retirement may leave both packages on disk; a disabled successor must stay disabled.
    // What a replacement supersedes is declared by that plugin (`supersession.ts`), never named here.
    loadPluginContributions: async <D, T>(input: { readonly workspaceId: string; readonly definition: PluginContributionDefinition<D, T> }, options: LoadPluginContributionsOptional = {}) => {
      const verdicts = await owner.findTrustedPluginPackages({ workspaceId: input.workspaceId, filename: input.definition.filename,
        contribution: input.definition.contribution, requireActive: false });
      const supersessions = await readSupersessions({ verdicts, manifests });
      const definition = { ...input.definition, load: async (context: Parameters<typeof input.definition.load>[0]) =>
        supersededDescriptorRefusal({ supersessions, pluginId: context.plugin.pluginId, descriptor: context.descriptor }) ?? input.definition.load(context) };
      return owner.loadPluginContributions({ ...input, definition }, { ...options, packageRefusal: ({ plugin }) =>
        supersededPackageRefusal({ supersessions, pluginId: plugin.pluginId }) ?? options.packageRefusal?.({ plugin }) });
    },
    installAgentPlugin: (input: InstallAgentPluginRequired, options: Parameters<typeof owner.installAgentPlugin>[1] = {}) => owner.installAgentPlugin({ ...input, layout: ownerLayout(input.layout), archiveReader: ownerReader(input.archiveReader) }, options),
    updateAgentPlugin: (input: Omit<import("@jini-ai/agent-plugins/lifecycle").UpdateAgentPluginRequired, "layout" | "archiveReader"> & { layout: AgentPluginLayout; archiveReader: AgentPluginArchiveReaderPort }) => owner.updateAgentPlugin({ ...input, layout: ownerLayout(input.layout), archiveReader: ownerReader(input.archiveReader) }),
    uninstallAgentPlugin: (input: UninstallAgentPluginRequired, options: Parameters<typeof owner.uninstallAgentPlugin>[1] = {}) => owner.uninstallAgentPlugin({ ...input, layout: ownerLayout(input.layout) }, options),
    previewAgentPluginUninstall: (input: UninstallAgentPluginRequired) => owner.previewAgentPluginUninstall({ ...input, layout: ownerLayout(input.layout) }),
    seedBundledAgentPlugins: (input: SeedBundledAgentPluginsRequired) => owner.seedBundledAgentPlugins({ ...input, layout: ownerLayout(input.layout) }),
    retireBundledAgentPlugins: (input: RetireBundledAgentPluginsRequired, options: Parameters<typeof owner.retireBundledAgentPlugins>[1] = {}) => owner.retireBundledAgentPlugins({ ...input, layout: ownerLayout(input.layout) }, options),
    resolveAgentPluginRefs: (pluginRefIds: readonly string[], workspaceLayout: Pick<AgentPluginWorkspaceLayout, "packages" | "root">, deliveryMode = resolveAgentPluginDeliveryMode()) => resolveHostPluginRefs({ pluginRefIds, workspaceLayout }, { deliveryMode }),
    resolveAgentPluginGuidance: resolveHostPluginRefs,
    listInstalledPlugins: (workspaceRoot: string) => owner.listInstalledPlugins({ workspaceRoot }),
    isInstalledDigestPresent: (packagesDir: string, archiveDigest: string) => owner.isInstalledDigestPresent({ packagesDir, archiveDigest }),
    indexInstalledRoot: (packageRoot: string, archiveDigest: string) => owner.indexInstalledRoot({ packageRoot, archiveDigest }),
    maxAgentPluginInstallArchiveBytes: () => owner.maxAgentPluginInstallArchiveBytes({}),
    normalizePackageEntryPath: (rawEntryPath: string) => owner.normalizePackageEntryPath({ rawEntryPath }),
    assertContainedOnDisk: (packageRoot: string, entryPath: string) => owner.assertContainedOnDisk({ packageRoot, entryPath }),
    readBundledAgentPluginDigests: (workspaceRoot: string) => owner.readBundledAgentPluginDigests({ workspaceRoot }),
    normalizeBundledDigests: (value: unknown) => owner.normalizeBundledDigests({ value }),
    preferBundledAgentPluginDigests: <T extends { readonly pluginId: string; readonly archiveDigest: string }>(installed: readonly T[], bundled: Parameters<typeof owner.preferBundledAgentPluginDigests>[0]['bundled']) => owner.preferBundledAgentPluginDigests({ installed, bundled }),
    recordBundledAgentPluginDigests: (input: Parameters<typeof owner.recordBundledAgentPluginDigests>[0] & { readonly now?: () => Date }) => owner.recordBundledAgentPluginDigests(input, input.now ? { now: input.now } : {}),
    rankInstalledAgentPlugins: (query: string, candidates: Parameters<typeof owner.rankInstalledAgentPlugins>[0]['candidates'], limit: number, optional: { automatic?: boolean } = {}) => owner.rankInstalledAgentPlugins({ query, candidates, limit }, optional),
    packAgentPluginDirectory: (sourceDir: string) => owner.packAgentPluginDirectory({ sourceDir }),
    createBundledSourceArchiveReader: (): AgentPluginArchiveReaderPort => {
      const reader = owner.createBundledSourceArchiveReader({});
      return { async *entries(archive) {
        for await (const entry of reader.entries({ archive })) yield entry.kind === "file" ? { ...entry, openReadStream: () => entry.openReadStream({}) } : entry;
      } };
    },
    findTrustedPluginPackages: ({ onInactive, ...input }: TrustedPluginPackagesQuery) => owner.findTrustedPluginPackages(input, onInactive ? { onInactive: ({ plugin }) => onInactive(plugin) } : {}),
    readTrustedPluginFile: (plugin: TrustedPluginPackage, filename: string) => owner.readTrustedPluginFile({ plugin, filename }),
    importContainedModule: (plugin: TrustedPluginPackage, modulePath: string) => owner.importContainedModule({ plugin, modulePath }),
  };
}

/** Compatibility exports below accept explicit roots/layouts. Site-dependent operations must use
 * a lifecycle bound at boot; importing this module must never select a site from process state. */
export const unboundSiteAgentPluginLayout: AgentPluginLayout = {
  root: "", workspacesDir: "",
  forWorkspace() { throw new Error("Agent Plugin layout must be supplied by the booted site binding"); },
};
const explicitRootLifecycle = createTovuAgentPluginLifecycle({ layout: unboundSiteAgentPluginLayout });
export const {
  installAgentPlugin, uninstallAgentPlugin, previewAgentPluginUninstall, stageForRemoval,
  restoreStagedTrees, removeFrozenPackageTree, seedBundledAgentPlugins, retireBundledAgentPlugins,
  resolveAgentPluginRefs, resolveAgentPluginGuidance, listInstalledPlugins, isInstalledDigestPresent, indexInstalledRoot,
  maxAgentPluginInstallArchiveBytes, normalizePackageEntryPath, assertContainedOnDisk,
  readBundledAgentPluginDigests, normalizeBundledDigests, preferBundledAgentPluginDigests,
  recordBundledAgentPluginDigests, removeBundledAgentPluginDigest, rankInstalledAgentPlugins,
  packAgentPluginDirectory, createBundledSourceArchiveReader,
  readTrustedPluginFile, importContainedModule, loadPluginContributionsFromSource,
  readInstalledSkillFile,
} = explicitRootLifecycle;

/** This boot's lifecycle owner; installed contributions always use its fixed site layout. */
export type TovuAgentPluginLifecycle = ReturnType<typeof createTovuAgentPluginLifecycle>;
export type LoadPluginContributions = TovuAgentPluginLifecycle["loadPluginContributions"];

/** Installed packages and manifests by explicit workspace root, for the Soon lock (`soon-lock.ts`). */
export const explicitRootSoonCatalog = explicitRootLifecycle.soonCatalog;

/** Compatibility activation effects take explicit workspace roots and cannot discover a site. */
export const explicitRootAgentPluginActivations = {
  reconcileAgentPluginActivation: explicitRootLifecycle.reconcileAgentPluginActivation,
  setAgentPluginActivation: explicitRootLifecycle.setAgentPluginActivation,
  recordBundledAgentPluginIfAbsent: explicitRootLifecycle.recordBundledAgentPluginIfAbsent,
  enableBundledAgentPluginUnlessOperatorDisabled: explicitRootLifecycle.enableBundledAgentPluginUnlessOperatorDisabled,
  deleteAgentPluginActivation: explicitRootLifecycle.deleteAgentPluginActivation,
  isAgentPluginActive: explicitRootLifecycle.isAgentPluginActive,
  filterActiveAgentPlugins: explicitRootLifecycle.filterActiveAgentPlugins,
  readAgentPluginActivations: explicitRootLifecycle.readAgentPluginActivations,
  assertAgentPluginActivationsWritable: explicitRootLifecycle.assertAgentPluginActivationsWritable,
  isAgentPluginRecordedAsBundled: explicitRootLifecycle.isAgentPluginRecordedAsBundled,
  resolveAgentPluginActivation: explicitRootLifecycle.resolveAgentPluginActivation,
  normalizeActivations: explicitRootLifecycle.normalizeActivations,
};

/** Object-shaped state containment port over the existing lifecycle path guard. @complexity O(path depth). */
export function containAgentPluginStatePath(required: { root: string; entryPath: string }, _optional: Record<string, never> = {}): Promise<string> {
  return explicitRootLifecycle.assertContainedOnDisk(required.root, required.entryPath);
}

import type { Tracker } from "@jini-ai/diagnostics/observability";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { nowIso, type Clock } from "@jini-ai/core/primitives";
import { firstExportFailure } from '@jini-ai/devops/static-export/failure-summary';
/**
 * @file The static-site export run's process-local single-flight state, extracted out of
 * `server/routes/admin/system/export-site.ts` (2026-08-15) so a SECOND caller — the
 * `deployment_trigger_export`/`deployment_get_export_status` agent tools and the read-only
 * `deployment_diagnose_static_export` (which reserves the same slot for a disposable export)
 * (`tool-registrations.ts` in this same directory) — can trigger and poll the exact same run the
 * admin UI's Deployment panel already does, instead of reimplementing it against a second,
 * independent `currentRun` slot.
 *
 * Ownership moved here rather than staying in the route file for the reason every other
 * `features/<domain>/tool-registrations.ts` in this codebase already establishes (see
 * `features/recovery/tool-registrations.ts`'s file header): a domain's `tool-registrations.ts`
 * must never import from `src/server/**` — doing so is exactly the "back-edge into the composition
 * root" `development/scripts/check-architecture.ts` measures.
 *
 * THIS FILE ALSO NEVER IMPORTS `#src/features/site-export/index` (the real `exportSite`/`ExportReport`), and that
 * is not the same "narrow-slice style" choice — it is a REQUIRED fix for a real bug the first
 * version of this file shipped with, now history. That first version imported `exportSite` directly,
 * and back then `src/features/site-export/site-exporter.ts` imported `createApp` from `server/app.ts`,
 * whose module body ended with an EAGER `export const app = createApp();` that ran the whole
 * app-boot call graph (including, via the BYOK execution mode, `buildAssistantToolRegistrations`) as
 * a side effect of merely LOADING `server/app.ts` — closing a real cycle: `assistant/
 * tool-registrations.ts` (loading) -> this domain's `tool-registrations.ts` -> this file ->
 * `export/index.ts` -> `site-exporter.ts` -> `server/app.ts` -> (via `modules/assistant-byok.ts`/
 * `byok-tool-surface.ts`) back into the STILL-LOADING `assistant/tool-registrations.ts`, calling
 * `buildAssistantToolRegistrations` before that module had reached its own `const DOMAIN_SLICES =
 * [...]` line. Observed directly at the time: `node --test`ing `tool-registrations.contracts.test.ts`
 * threw `ReferenceError: Cannot access 'DOMAIN_SLICES' before initialization`.
 *
 * Both halves of that cycle are gone now: `site-exporter.ts` has taken `routeDeps.createSiteApp()`
 * instead of importing `createApp` from `app.ts` since 2026-08-16, and the eager `export const app =
 * createApp();` itself was removed on 2026-09-16 (t91 F4.1). This file still never imports
 * `#src/features/site-export/index` directly — the injection below stays, not because the crash could
 * still happen, but because it keeps `features/deployments` from depending on the export engine's
 * whole graph at all.
 *
 * The fix is dependency injection instead of an import: {@link startExportRun} takes the actual
 * export engine as a parameter (typed structurally via {@link ExportEngine}, never by naming
 * `ExportSiteOptions`/`ExportReport`), and `RouteDeps.runExportSite`
 * (`server/routes/types.ts`) is where the real `exportSite` function is bound — exactly once, in
 * `server/app.ts`'s `createRouteDeps()` and `server/deps.ts`'s `createSiteRouteDeps()`, the two
 * places that are safe to import `#src/features/site-export/index` directly (neither is reachable FROM
 * `assistant/tool-registrations.ts`, so no cycle closes). Both callers of `startExportRun` —
 * `export-site.ts`'s POST handler and this domain's `deployment_trigger_export` handler — pass
 * `routeDeps.runExportSite` straight through; neither imports `#src/features/site-export/index` either.
 *
 * DISCLOSED CROSS-PROCESS GAP: this module's `currentRun` is a plain in-memory module variable, so
 * it is single-flight-correct only WITHIN one OS process. Tovu's admin HTTP server and the
 * standalone agent daemon (`assistant/agent-daemon-server.ts`, "a separate OS process from Tovu's
 * own server" per its own file header) each load their own independent copy of this module when
 * `buildDeploymentsRegistrations` is wired into them — there is no cross-process lock. A human
 * clicking "Export" in the admin UI at the same moment an agent (running through the daemon)
 * calls `deployment_trigger_export` could therefore both observe "not running" and both start
 * writing into the same `outputDir` concurrently. This is the same class of caveat
 * `agent-daemon-server.ts`'s own header already discloses for `TOVU_DB=memory` ("writes would not
 * be visible from Tovu's main process") — disclosed here rather than silently assumed away. Closing
 * it for real needs either a cross-process lock (e.g. a lockfile under `outputDir`) or routing the
 * daemon's trigger back over HTTP to the main process, both out of scope for this wiring pass. The
 * BYOK execution mode (`server/modules/assistant-byok.ts`, which composes the SAME tool catalog
 * in-process inside the main server) is unaffected — it shares this exact module instance with the
 * HTTP route, so single-flight holds there.
 */

export type ExportRunStatus = "idle" | "running" | "completed" | "errored";

export interface ExportRunCounts {
  routesSucceeded: number;
  routesFailed: number;
  assetsSucceeded: number;
  assetsFailed: number;
}

/**
 * The full-fidelity, JSON-transportable status of the current/most recent export run. Moved
 * verbatim from `export-site.ts` — see that file's history for the original "why narrower than
 * `ExportReport`" rationale (peak-memory bytes are never echoed back; only counts plus full failure
 * detail).
 */
export interface ExportRunSnapshot {
  status: ExportRunStatus;
  startedAtIso: string | null;
  finishedAtIso: string | null;
  outputDir: string | null;
  /** Present only once `status` is `"completed"`. */
  basePath?: string;
  /** Present only once `status` is `"completed"`. Failed routes or assets make the copy incomplete. */
  ok?: boolean;
  counts?: ExportRunCounts;
  failedRoutes?: { path: string; kind: string; reason: string }[];
  failedAssets?: { url: string; reason: string }[];
  skippedManifestEntries?: { reason: string; detail: string }[];
  unreferencedThemeFiles?: string[];
  droppedReferences?: { page: string; url: string; attribute: string; reason: "not-exported" | "needs-server" }[];
  basePathRewriteWarning?: string;
  /** Present only when `status` is `"errored"` — always a message, never the raw error object. */
  error?: string;
}

/**
 * A structural mirror of `src/features/site-export/site-exporter.ts`'s `ExportReport` — only the fields
 * {@link summarizeCompletedReport} actually reads. Declared locally, never imported, per this
 * file's header. The real `ExportReport` satisfies this structurally (it has every field below,
 * with compatible types), so passing the real `exportSite` as an {@link ExportEngine} type-checks
 * with no cast at the one place it is actually bound (`server/app.ts`/`server/deps.ts`).
 */
export interface ExportRunReportLike {
  routes: { succeeded: unknown[]; failed: { path: string; kind: string; reason: string }[] };
  assets: { succeeded: unknown[]; failed: { url: string; reason: string }[] };
  skippedManifestEntries: { reason: string; detail: string }[];
  unreferencedThemeFiles: string[];
  /** Bounded by the export engine to at most 200 entries. */
  droppedReferences: { page: string; url: string; attribute: string; reason: "not-exported" | "needs-server" }[];
  basePath?: string;
  basePathRewriteWarning?: string;
}

/**
 * The injected shape of `src/features/site-export/site-exporter.ts`'s `exportSite`, generic over whatever
 * `routeDeps` type the caller carries (in every real caller, `RouteDeps` itself — see this file's
 * header for why that is never spelled out by name here).
 */
export type ExportEngine<TRouteDeps> = (options: {
  routeDeps: TRouteDeps;
  outputDir: string;
  clean?: boolean;
  basePath?: string;
}) => Promise<ExportRunReportLike>;

const IDLE_RUN: ExportRunSnapshot = { status: "idle", startedAtIso: null, finishedAtIso: null, outputDir: null };

/** Process-local mutable slot — see this file's header for exactly which callers share ONE
 *  instance of it and which do not. */
let currentRun: ExportRunSnapshot = IDLE_RUN;

/** Slims a full export report down to `ExportRunSnapshot`'s "completed" fields — moved verbatim
 *  from `export-site.ts`. */
function summarizeCompletedReport(report: ExportRunReportLike): Pick<
  ExportRunSnapshot,
  "basePath" | "ok" | "counts" | "failedRoutes" | "failedAssets" | "skippedManifestEntries" | "unreferencedThemeFiles" | "droppedReferences" | "basePathRewriteWarning"
> {
  return {
    ...(report.basePath !== undefined ? { basePath: report.basePath } : {}),
    ok: firstExportFailure({ report }) === undefined,
    counts: {
      routesSucceeded: report.routes.succeeded.length,
      routesFailed: report.routes.failed.length,
      assetsSucceeded: report.assets.succeeded.length,
      assetsFailed: report.assets.failed.length,
    },
    failedRoutes: report.routes.failed.map((f) => ({ path: f.path, kind: f.kind, reason: f.reason })),
    failedAssets: report.assets.failed.map((f) => ({ url: f.url, reason: f.reason })),
    skippedManifestEntries: report.skippedManifestEntries,
    unreferencedThemeFiles: report.unreferencedThemeFiles,
    droppedReferences: report.droppedReferences,
    ...(report.basePathRewriteWarning !== undefined ? { basePathRewriteWarning: report.basePathRewriteWarning } : {}),
  };
}

/**
 * The current/most recent export run's status, exactly as the HTTP status-poll route reports it.
 *
 * @returns `IDLE_RUN` if no run has ever started in this process.
 * @complexity O(1).
 */
export function getExportRunSnapshot(): ExportRunSnapshot {
  return currentRun;
}

/**
 * Starts a new export run unconditionally and returns the "running" snapshot immediately — the
 * export itself continues in the background (see this file's header: "seconds to minutes").
 *
 * Caller contract: the caller must have already confirmed `getExportRunSnapshot().status !==
 * "running"` in the SAME synchronous stretch of the event loop, with no `await` in between (both
 * `export-site.ts`'s POST handler and `tool-registrations.ts`'s `deployment_trigger_export` handler
 * do exactly this) — that is what makes "one export at a time" hold even under two concurrent
 * callers in the same process. This function does not re-check, so calling it while a run is
 * already in flight would silently start a second one; it is deliberately not the guard itself.
 *
 * @param required.routeDeps - The same full composition-root deps object the injected `runExportSite` needs
 * to boot an in-process copy of the app. Opaque to this function beyond `.clock.nowMs()` and
 * `.exportOutputRootDir` — passed straight through to `runExportSite`. `exportOutputRootDir` is
 * `RouteDeps.exportOutputRootDir` (`TOVU_EXPORT_DIR` env, then the served site's `out/export`), resolved ONCE
 * by the composition root (`server/app.ts`/`server/deps.ts`) — this function never reads
 * `process.env` itself, and a test overrides the directory by setting this field on the fake
 * `routeDeps` it constructs, not by mutating real process env vars.
 * @param required.runExportSite - The actual export engine, injected by the caller — see this file's header
 * for why it is never imported here directly. In production this is always `routeDeps.runExportSite`
 * (bound to the real `exportSite` by `server/app.ts`/`server/deps.ts`).
 * @param required.clean - Forwarded to `runExportSite`; wipes `outputDir` first when `true`.
 * @param optional.basePath - Forwarded to `runExportSite`; see `ExportSiteOptions.basePath`'s own doc
 * (`site-exporter.ts`).
 * @param optional.onSettled - Told the run's final status once it settles (the route's product event).
 * @returns The new "running" snapshot (not a promise — the export's own completion is observed
 * later via {@link getExportRunSnapshot}).
 * @complexity O(1) synchronously; the awaited export itself is O(routes + assets) over HTTP, per
 * `site-exporter.ts`'s own complexity note.
 */
export function startExportRun<TRouteDeps extends { clock: Clock; exportOutputRootDir: string }>(
  required: { routeDeps: TRouteDeps; runExportSite: ExportEngine<TRouteDeps>; clean: boolean },
  optional?: { basePath?: string; productEvent?: { tracker: Tracker; userId: string; operationId: string; source: "admin" | "assistant" }; onSettled?: (settled: { status: "completed" | "errored" }) => void },
): ExportRunSnapshot {
  const { routeDeps, runExportSite, clean } = required;
  const outputDir = routeDeps.exportOutputRootDir;
  const startedAtIso = nowIso({ clock: routeDeps.clock });
  currentRun = { status: "running", startedAtIso, finishedAtIso: null, outputDir };

  // Deliberately not awaited — the caller (an HTTP route or a tool handler) returns the "running"
  // snapshot immediately; a later poll observes the outcome via getExportRunSnapshot(). Both
  // branches always update currentRun, so a poller can never observe a stale "running" snapshot
  // after the promise has actually settled.
  void runExportSite({ routeDeps, outputDir, clean, basePath: optional?.basePath })
    .then((report) => {
      currentRun = {
        status: "completed",
        startedAtIso,
        finishedAtIso: nowIso({ clock: routeDeps.clock }),
        outputDir,
        ...summarizeCompletedReport(report),
      };
    })
    .catch((err: unknown) => {
      currentRun = {
        status: "errored",
        startedAtIso,
        finishedAtIso: nowIso({ clock: routeDeps.clock }),
        outputDir,
        error: err instanceof Error ? err.message : String(err),
      };
    })
    .finally(() => {
      const status = currentRun.status === "completed" ? "completed" : "errored";
      const event = optional?.productEvent;
      event?.tracker.capture({ name: "site_exported", userId: event.userId }, { properties: { outcome: status, operationId: event.operationId, eventId: `export:${event.operationId}`, source: event.source } });
      optional?.onSettled?.({ status });
    });

  return currentRun;
}

/** Refuse a concurrent trigger or diagnostic using the process-local owner of export state. */
export function assertExportNotRunning(_required: Record<string, never>, _optional: Record<string, never> = {}): void {
  if (currentRun.status === "running") {
    throw Object.assign(new Error("an export is already running — call deployment_get_export_status to see its progress, this will not resolve on retry"), { code: "ALREADY_RUNNING" });
  }
}

/** Run the injected engine in disposable storage and return only report diagnostics.
 * Reserves currentRun before the first await; restores the previous status after cleanup.
 * Engine/storage errors propagate, and the slot is released even if cleanup fails.
 * @complexity One export pass plus removal of its temporary output files.
 */
export async function diagnoseStaticExport<TRouteDeps extends { clock: Clock }>(
  required: { routeDeps: TRouteDeps; runExportSite: ExportEngine<TRouteDeps> },
  _optional: Record<string, never> = {},
): Promise<ReturnType<typeof summarizeCompletedReport>> {
  assertExportNotRunning({});
  const previous = currentRun;
  currentRun = { status: "running", startedAtIso: nowIso({ clock: required.routeDeps.clock }), finishedAtIso: null, outputDir: null };
  let outputDir: string | undefined;
  try {
    outputDir = await mkdtemp(path.join(tmpdir(), "static-export-diagnostics-"));
    currentRun = { ...currentRun, outputDir };
    const report = await required.runExportSite({ routeDeps: required.routeDeps, outputDir, clean: false });
    return summarizeCompletedReport(report);
  } finally {
    try { if (outputDir !== undefined) await rm(outputDir, { recursive: true, force: true }); }
    finally { currentRun = previous; }
  }
}

