const CATALOG_BY_ID = indexCatalogById({ catalog: staticPublishAgentToolCatalog });

/**
 * This wiring layer's OWN risk classification, independent of the catalog's `sideEffects`
 * declaration (`@jini-ai/cms/core`'s `assertToolIsWirable` cross-checks the two and refuses to wire
 * on disagreement).
 */
export const staticPublishDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> resolves credential presence (`PublishCredentialSource.isConfigured`, read-only) and validates
  // config shape (`validateStaticPublishConfig`, pure). Authenticated provider inspection may
  // resolve server-side for GETs only; no provisioning, uploads or export run.
  ["deployment_preview_static_publish", "none"],
  ["deployment_get_static_publish_status", "none"],
  // -> `listPublishCredentials` (a pure DB read, never decrypts — `publish-credentials/store.ts`'s own
  // doc) plus `PublishCredentialSource.isConfigured` per provider (same non-decrypting contract the
  // preview tool relies on). No write, no decrypt, no network call.
  ["deployment_get_static_publish_capabilities", "none"],
  // -> on confirm, calls `publishStaticSite`: a real `exportSite` pass plus a real provider API call
  // (the selected host plugin's deploy target) using a write-scoped credential — genuinely mutates
  // external durable state. See this file's header for the full risk story.
  ["deployment_execute_static_publish", "mutates-durable-state"],
  // -> on submit, calls `createPublishCredential`/`updatePublishCredential` — a real encrypted write to
  // `vendor_credential_sets`.
  // No secret ever transits the model (see this file's header/the catalog entry's own comment); the
  // write itself is still a genuine external-account-scoped mutation, same category (not merely "some
  // risk classification") as the publish tool above.

  // -> the host plugin module's pure `hostingSetup` over the caller's non-secret fields (never a saved
  // credential). No write, no network call, no decrypt.
  ["deployment_generate_bucket_hosting_setup", "none"],
]);

/** {@link StaticPublishToolDeps.loadDeployTargets}, bound by composition to installed plugins or trusted source. */
function deployTargetsLoader(deps: StaticPublishToolDeps): (workspaceId: string) => Promise<DeployTargetRegistry> {
  return deps.loadDeployTargets;
}

/**
 * Reads a tool input into a publish config for `target` (already looked up in `registry`) and plans
 * it (`planStaticPublish`, the same call `publishStaticSite` makes). A blank optional field means "not
 * set", matching the old per-target builders.
 *
 * @throws {ToolInputError} A declared field is not a string.
 * @complexity O(f) declared fields.
 */
function planToolPublish(
  registry: DeployTargetRegistry,
  raw: Record<string, unknown>,
  target: LoadedDeployTarget
): { readonly config: StaticPublishConfig; readonly plan: ReturnType<typeof planStaticPublish>; readonly detailRows: DetailRow[] } {
  requireOnlyDeclaredFields(raw, target.descriptor);
  const read = readStaticPublishConfig(target, raw, { blankAsAbsent: true });
  if (!read.ok) throw new ToolInputError({ message: read.message });
  return { config: read.config, plan: planStaticPublish(registry, read.config), detailRows: configDetailRows(read.config, target) };
}

/** The publish request's own keys; every other input key must be one of the host's config fields. */
const PUBLISH_REQUEST_KEYS: ReadonlySet<string> = new Set(["target", "projectName", "credentialId"]);

/** Only the explicit, non-secret connection choice crosses into the publish input. */
function toolCredentialChoice({ raw }: { raw: Readonly<Record<string, unknown>> }, _options = {}): { credentialId?: string } {
  if (raw.credentialId === undefined) return {};
  if (typeof raw.credentialId !== "string" || !raw.credentialId.trim()) throw new ToolInputError({ message: "credentialId must be a non-empty string naming the person's selected connection. Choose it again before previewing or executing." });
  return { credentialId: raw.credentialId };
}

/** Refuses an input key the chosen host does not declare, so nothing (a token included) reaches a
 *  publish except the host's own config fields. The schemas allow any string key because the fields
 *  come from the host's descriptor.
 *  @throws {ToolInputError} naming the first undeclared key and the fields the host takes.
 *  @complexity O(k·f) input keys by declared fields. */
function requireOnlyDeclaredFields(raw: Record<string, unknown>, descriptor: DeployTargetDescriptor): void {
  const declared = descriptor.configFields.map((field) => field.name);
  const unknown = Object.keys(raw).find((key) => !PUBLISH_REQUEST_KEYS.has(key) && !declared.includes(key));
  if (unknown === undefined) return;
  const takes = declared.length > 0 ? `It takes: ${declared.join(", ")}.` : "It takes no config fields.";
  throw new ToolInputError({ message: `'${unknown}' is not a field of ${descriptor.id}. ${takes}` });
}

/** One labelled row on a publish confirmation/outcome card. */
type DetailRow = { label: string; value: string };

/** The card rows for a publish: the target module's own `summarize` when it has one, otherwise one
 *  row per declared config field the publish carries, in declaration order and under its declared
 *  label. Which fields exist is the plugin's business, so nothing here names a host.
 *  @complexity O(f) declared fields. */
function configDetailRows(config: StaticPublishConfig, target: LoadedDeployTarget): DetailRow[] {
  if (target.module.summarize !== undefined) return target.module.summarize(config).map(({ label, value }) => ({ label, value }));
  return target.descriptor.configFields.flatMap((field) => {
    const value = config[field.name];
    return typeof value === "string" ? [{ label: field.label, value }] : [];
  });
}

const EXECUTE_STATIC_PUBLISH_TOOL_ID = "deployment_execute_static_publish";

/** The `ui://` URI for one publish-confirmation instance. Keyed by the exchange id (unique per raised
 *  dialog) rather than by an entity+version the way `deleteConfirmationUri`
 *  (`features/post/delete-confirmation-ui.ts`) keys its own — a publish has no existing row/version to
 *  key against, so the exchange id is what keeps two dialogs raised for the same target from
 *  colliding on one URI. */
function publishConfirmationUri(exchangeId: string): UIResourceUri {
  return `ui://tovu/deployment-execute-static-publish/${exchangeId}` as UIResourceUri;
}

/**
 * Renders the RESULT of a confirmed publish — what a human sees replacing the confirmation dialog
 * they just answered, once `askThenReport`'s `handle` callback has actually run `publishStaticSite`
 * (or refused to, e.g. `already-running`). See `assistant/surface-exchanges.ts`'s `askThenReport` doc
 * for the mechanism this depends on: sent under the SAME `uri` the confirmation used
 * (`publishConfirmationUri(exchangeId)`, deliberately reused rather than a fresh one), which is what
 * makes `McpUiSurfaceCard` (`@jini-ai/chat`) replace the dialog in place instead of opening a second
 * card, and what makes `McpUiHost` remount the frame cleanly (its `sessionKey` is
 * `` `${uri}:${documentText}` ``, and this document's text always differs from the confirmation's).
 *
 * `state`/`message`/`url` map straight onto Jini's `SurfaceOutcomeSpec` (`@jini-ai/ui/mcp-ui/surfaces`'s
 * `outcome.ts`) — this function's own job is only deciding the publish-specific title/details/labels,
 * the same division of labor `buildPublishConfirmationResource` above already has with
 * `buildConfirmationSurface`.
 *
 * @param spec.url - Present for `'success'` and `'partial'` only — renders one "Open site"/"Open when
 *   ready" button wired to the bridge's existing `openLink`, no new bridge plumbing. Omitted for
 *   `'failure'`: there is nothing live to open.
 * @complexity O(1) — fixed-size field reads, no iteration.
 */
function buildPublishOutcomeResource(spec: {
  exchangeId: string;
  config: StaticPublishConfig;
  detailRows: readonly DetailRow[];
  projectName: string;
  state: "success" | "partial" | "failure";
  message: string;
  url?: string;
}): UIResource {
  const { exchangeId, config, detailRows, projectName, state, message, url } = spec;
  const unsuccessfulTitle = state === "partial" ? "Uploaded, not live yet" : "Publish failed";
  const title = state === "success" ? "Published" : unsuccessfulTitle;
  return buildOutcomeSurface({
    uri: publishConfirmationUri(exchangeId),
    title,
    details: [
      { label: "Target", value: config.target },
      { label: "Project name", value: projectName },
      ...detailRows,
    ],
    state,
    message,
    ...(url !== undefined ? { openLinkUrl: url, openLinkLabel: state === "partial" ? "Open when ready" : "Open site" } : {}),
    app: { appName: "tovu-deployment-execute-static-publish-outcome", appVersion: "1" },
    preferredFrameSize: ["100%", "360px"],
  });
}



/** The label prefix a credential saved from chat is created under — mirrors
 *  `apps/admin/src/features/deployment/rules.ts`'s `PUBLISH_CREDENTIAL_ROW_LABEL` ("default"). Cannot
 *  be imported directly: `apps/admin` is a genuinely separate npm workspace with no import path into
 *  this server's `src/` (spec §5's own verified finding), so this is a deliberate, documented mirror
 *  rather than a shared constant — an operator never sees or types a label for this provider on
 *  either side (spec §4c/§9). New project rows add an id suffix because other sites' unattached
 *  keys are deliberately invisible here and must never block or be overwritten by a new save. */
const CUSTOM_PROVIDER_CREDENTIAL_ROW_LABEL = "default";

/** The `ui://` URI for one propose-credential form instance — same "keyed by exchange id, not an
 *  entity+version" reasoning `publishConfirmationUri` above documents (there is no existing row to key
 *  a fresh save against). */
// The engine supplies this exchange-keyed URI to both the form and its outcome.

/** Shared `target` lookup for `deployment_preview_static_publish` and
 *  `deployment_execute_static_publish`: the input's `target` must be a host this workspace's deploy
 *  registry has loaded.
 *  @throws {ToolInputError} `raw.target` is missing, or no loaded plugin provides it.
 *  @complexity O(1) — one registry lookup. */
function requireStaticPublishTarget(raw: Record<string, unknown>, registry: DeployTargetRegistry): LoadedDeployTarget {
  const targetId = requireString({ input: raw, key: "target" });
  const target = registry.get(targetId);
  if (target === undefined) throw new ToolInputError({ message: unknownTargetMessage(registry, targetId) });
  return target;
}

/** `deployment_preview_static_publish`'s result shape — extracted purely to keep that handler's
 *  own body a flat sequence of steps. */
function buildStaticPublishPreviewResult(
  target: StaticPublishTargetId,
  validationError: string | null,
  basePath: string | undefined,
  credential: { readonly configured: boolean; readonly reason?: string }
) {
  return {
    target,
    valid: validationError === null,
    ...(validationError !== null ? { validationError } : {}),
    basePath: basePath ?? null,
    credentialsConfigured: credential.configured,
    ...(!credential.configured ? { credentialGuidance: credential.reason } : {}),
  };
}

/** Per-provider dependencies {@link buildProviderCapability} needs — the already-fetched credential
 *  summaries plus every port it reads, so the capabilities handler's `registry.list().map()` callback
 *  stays a single call per provider rather than a long inline closure. */
interface ProviderCapabilityContext {
  readonly deps: StaticPublishToolDeps;
  readonly credentialSource: PublishCredentialSource;
  readonly historyStore: PublishHistoryStore;
  readonly saved: Awaited<ReturnType<typeof listPublishCredentials>>;
}

/** {@link buildProviderCapability}'s `savedCredentials` entries: no secret, only the token's last 4. */
function mapSavedCredentials(saved: Awaited<ReturnType<typeof listPublishCredentials>>) {
  return saved.map(({ id, label, isDefault, createdAt, updatedAt, tokenTail, tokenHint, credentialType, worksFor }) => ({ id, label, isDefault, createdAt, updatedAt, tokenTail, tokenHint, credentialType, worksFor }));
}

/**
 * {@link buildProviderCapability}'s result-object assembly, split out from the value computation so
 * neither half alone carries every branch in the original 100-line closure. `verifiedAt`/`accountLabel`
 * are the two fields this handler still needs beyond what {@link buildCapabilityGuidance} itself reads.
 *
 * accountLabel prefers the default credential's stored column, healed by post-save verification,
 * and falls back to cached verification only when that column is null (an unhealed or env-only row).
 * Stored identity survives restart while the cache does not, and prevents guessing a GitHub account
 * from the human's email instead of using the verified token's actual account.
 */
function buildProviderCapabilityResult(spec: {
  readonly descriptor: DeployTargetDescriptor;
  readonly ready: boolean;
  readonly readiness: { configured: true } | { configured: false; reason: string };
  readonly verified: "valid" | "invalid" | "unreachable" | null;
  readonly verification: ReturnType<PublishCredentialVerificationCache["get"]>;
  readonly defaultCredential: { readonly accountLabel: string | null } | undefined;
  readonly lastPublish: Awaited<ReturnType<PublishHistoryStore["getLast"]>>;
  readonly savedCredentials: ReturnType<typeof mapSavedCredentials>;
  readonly credentialOrigin: "saved" | "environment" | null;
  readonly guidance: string | undefined;
}, _options = {}) {
  const { descriptor, ready, readiness, verified, verification, defaultCredential, lastPublish, savedCredentials, credentialOrigin, guidance } = spec;
  return {
    providerId: descriptor.id,
    label: descriptor.label,
    // What a publish to this host takes, besides `target` and `projectName`: pass each as a
    // top-level string property of the same name.
    configFields: descriptor.configFields.map(({ name, label, required, help }) => ({ name, label, required, ...(help !== undefined ? { help } : {}) })),
    ready,
    credentialConfigured: readiness.configured,
    credentialOrigin,
    verified,
    verifiedAt: verification?.checkedAt ?? null,
    // The verified credential's own public account login/username, when the host's verifier
    // reports one — `null` when not yet verified, or for a provider whose verifier has no reviewed
    // account field to read (see `verify.ts`'s header).
    accountLabel: defaultCredential?.accountLabel ?? verification?.accountLabel ?? null,
    lastPublish,
    savedCredentials,
    ...(guidance !== undefined ? { guidance } : {}),
  };
}

/**
 * Computes one provider's `deployment_get_static_publish_capabilities` entry — extracted from that
 * handler's own `PROVIDER_IDS.map()` callback purely to keep this domain's complexity gates: this was
 * previously a single ~100-line inline async arrow.
 *
 * `savedCredentials` include only this host's explicitly compatible keys, with defaults selected
 * after compatibility and token-only shape filtering. `credentialConfigured` comes from
 * `credentialSource.isConfigured` (a saved default, or in self-hosted mode an env var).
 *
 * `ready` means "will actually work," not merely "a credential is saved" (2026-08-16 fix: a saved
 * GitHub token GitHub rejected outright with 401 used to still report `ready: true`) — a credential
 * that is configured but never verified, that failed its last verification, or whose last check could
 * not reach the provider is NOT ready.
 *
 * `verification` is a cached, non-decrypting read only — NEVER `verifyPublishCredential` from here
 * (that decrypts and makes a real provider call; see `static-publish/verify.ts`'s own header for why
 * this handler must never be its caller).
 */
async function buildProviderCapability(loaded: LoadedDeployTarget, ctx: ProviderCapabilityContext) {
  const providerId = loaded.descriptor.id;
  const savedForVendor = ctx.saved.filter(credential => credential.publishHosts.includes(providerId))
    .map(credential => ({ ...credential, isDefault: credential.defaultFor.includes(providerId) }));
  const savedCredentials = mapSavedCredentials(savedForVendor);
  const defaultCredential = savedForVendor.find((credential) => credential.isDefault);
  const readiness = await ctx.credentialSource.isConfigured({ workspaceId: ctx.deps.workspaceId, target: providerId });
  // 2026-08-16, Defect 2: the last successful publish to this provider, if any — see
  // `publish-history.ts`'s own header for the storage design. `null` means never published (from
  // this server, in this history store) rather than an absent key, so an agent-facing JSON result
  // always carries the field.
  const lastPublish = await ctx.historyStore.getLast({ workspaceId: ctx.deps.workspaceId, target: providerId });
  const verification = readiness.configured ? ctx.deps.publishCredentialVerificationCache.get({ workspaceId: ctx.deps.workspaceId, target: providerId }) : undefined;
  const verified = verification ? verification.status : null;
  const ready = readiness.configured && verified === "valid";
  const fallbackOrigin = readiness.configured ? "environment" : null;
  const credentialOrigin = savedCredentials.length ? "saved" : fallbackOrigin;
  const guidance = buildCapabilityGuidance({ providerId, readiness, verification, credentialOrigin });

  return { ...buildProviderCapabilityResult({ descriptor: loaded.descriptor, ready, readiness, verified, verification, defaultCredential, lastPublish, savedCredentials, credentialOrigin, guidance }),
    defaultForNewDestination: loaded.module.defaultForNewDestination === true,
    authenticatedPreview: loaded.module.preview !== undefined };
}

/** Preserve enabled-host readiness while exposing disabled/unknown hosts without claiming their
 * credentials were inspected. Only activation permits executable use; loader refusals remain visible.
 * @returns One host choice with explicit installation, activation and readiness states.
 * @complexity O(1) metadata; enabled hosts delegate to the existing credential/history read model.
 */
async function buildInstalledProviderCapability({ installed, registry, context }: {
  installed: InstalledDeployTarget; registry: DeployTargetRegistry; context: ProviderCapabilityContext;
}, _optional: Record<string, never> = {}) {
  const loaded = registry.get(installed.descriptor.id);
  const identity = { pluginId: installed.pluginId, enabled: installed.enabled };
  if (installed.enabled === true && loaded?.pluginId === installed.pluginId) {
    return { ...await buildProviderCapability(loaded, context), ...identity, executable: true };
  }
  return { providerId: installed.descriptor.id, label: installed.descriptor.label, ...identity,
    executable: false, ready: false, credentialConfigured: null, savedCredentials: null,
    guidance: installed.enabled === true
      ? "The hosting plugin is enabled but its target could not be loaded. Inspect refusals before publishing."
      : `Turn on Agent Plugin '${installed.pluginId}' under Admin → Agent Plugins, then call deployment_get_static_publish_capabilities again. Credentials and readiness have not been inspected for this host.` };
}

/** Every dependency {@link handlePublishConfirmationAnswer} needs to run the confirmed publish and
 *  report its result — bundled so `deployment_execute_static_publish`'s own `askThenReport` call
 *  passes a single object instead of the handler's whole closure. */
interface PublishConfirmationContext {
  readonly deps: StaticPublishToolDeps;
  readonly credentialSource: PublishCredentialSource;
  readonly historyStore: PublishHistoryStore;
  readonly exchange: SurfaceExchange;
  readonly config: StaticPublishConfig;
  /** The card's config rows, labelled from the target descriptor (see `configDetailRows`). */
  readonly detailRows: readonly DetailRow[];
  readonly target: StaticPublishTargetId;
  readonly projectName: string;
}

/**
 * Maps `publishStaticSite`'s own `StaticPublishOutcome` (via {@link handlePublishConfirmationAnswer}'s
 * `runPublishAndAwait` call) to `deployment_execute_static_publish`'s agent-facing result plus the
 * `outcome` emission that corrects the confirmation dialog with the truth (see
 * {@link handlePublishConfirmationAnswer}'s own header for why that emission exists at all).
 *
 * "Uploaded, but not yet reachable" (spec `custom-publish-provider-contract.md` §3a) — a `"partial"`
 * outcome's files DID upload (so `published: true`, never a hard failure), but the site is not
 * confirmed live yet (so `reachable: false`, never a plain success either). Structurally a distinct
 * branch from both — see `static-publish/types.ts`'s `StaticPublishOutcome` header for why
 * `outcome.ok` itself is `true | false | "partial"`, not merely a boolean.
 *
 * Every branch of `publishStaticSite`'s own failure contract (`static-publish/types.ts`'s
 * `StaticPublishOutcome` doc, `adapter.ts`'s own `catch`) is already an actionable, credential-free
 * message: `NO_CREDENTIALS_CONFIGURED` names the provider via the resolved credential source's own
 * reason text, a credential missing a host-required field (e.g. an account id) names the exact
 * missing field (the target's own `DeployError`), and `PROVIDER_ERROR` is `err.message` only — never a
 * raw response body, never a credential. Passed straight through rather than re-wrapped, and straight
 * into the outcome surface too — the same actionable text a human would need either way.
 */
function mapPublishOutcomeToToolResult(
  outcome: StaticPublishOutcome,
  exchange: Pick<SurfaceExchange, "id">,
  config: StaticPublishConfig,
  detailRows: readonly DetailRow[],
  projectName: string
): { result: unknown; outcome: SurfaceEmission } {
  if (!outcome.ok) {
    return {
      result: { published: false, cancelled: false, code: outcome.code, message: outcome.message, ...(outcome.credentialSetup ? { credentialSetup: outcome.credentialSetup } : {}) },
      outcome: {
        channel: "mcp-ui",
        payload: { resource: buildPublishOutcomeResource({ exchangeId: exchange.id, config, detailRows, projectName, state: "failure", message: outcome.message }) },
      },
    };
  }
  const published = {
    published: true, target: outcome.targetId, url: outcome.url, status: outcome.status,
    ...(outcome.providerMetadata ? { providerMetadata: outcome.providerMetadata } : {}),
    ...(outcome.deploymentId !== undefined ? { deploymentId: outcome.deploymentId } : {}),
    ...(outcome.basePath !== undefined ? { basePath: outcome.basePath } : {}),
    ...(outcome.consentWarning ? { consentWarning: outcome.consentWarning } : {}),
  };
  if (outcome.ok === "partial") {
    return {
      result: { ...published, reachable: false, message: outcome.message },
      outcome: {
        channel: "mcp-ui",
        payload: {
          resource: buildPublishOutcomeResource({ exchangeId: exchange.id, config, detailRows, projectName, state: "partial", message: [outcome.message, outcome.consentWarning].filter(Boolean).join(" "), url: outcome.url }),
        },
      },
    };
  }
  return {
    result: { ...published, reachable: true },
    outcome: {
      channel: "mcp-ui",
      payload: {
        resource: buildPublishOutcomeResource({
          exchangeId: exchange.id, config, detailRows, projectName, state: "success",
          message: [`Published live at ${outcome.url}.`, outcome.consentWarning].filter(Boolean).join(" "),
          url: outcome.url,
        }),
      },
    },
  };
}

/** The host whose credential the propose-credential tool saves: it must be loaded and declare one.
 *  @throws {ToolInputError} unknown host, or a host that takes no saved credential.
 *  @complexity O(1) — one registry lookup. */
function requireCredentialTarget(raw: Record<string, unknown>, registry: DeployTargetRegistry): { readonly descriptor: DeployTargetDescriptor; readonly credential: DeployTargetCredentialSpec } {
  const { descriptor } = requireStaticPublishTarget(raw, registry);
  if (descriptor.credential === undefined) throw new ToolInputError({ message: `${descriptor.id} takes no saved credential.` });
  return { descriptor, credential: descriptor.credential };
}

/**
 * The agent's non-secret credential-field values (form pre-fill, or hosting-setup input). Refuses a
 * secret field, so a secret can never come from the chat, and a field the host does not declare. A
 * blank value is left out.
 *
 * @throws {ToolInputError} naming the first refused key.
 * @complexity O(k·f) input keys by credential fields.
 */
function readCredentialHints(raw: Record<string, unknown>, descriptor: DeployTargetDescriptor): Record<string, string> {
  const fields = descriptor.credential?.fields ?? [];
  const hints: Record<string, string> = {};
  for (const [key, value] of Object.entries(raw)) {
    if (key === "target") continue;
    const field = fields.find((candidate) => candidate.name === key);
    if (field === undefined) {
      const takes = fields.length > 0 ? `It takes: ${fields.map((candidate) => candidate.name).join(", ")}.` : "It takes none.";
      throw new ToolInputError({ message: `'${key}' is not a credential field of ${descriptor.id}. ${takes}` });
    }
    const hint = readCredentialHint({ key, value, field, tokenField: descriptor.credential?.tokenField });
    if (hint.trim() !== "") hints[key] = hint;
  }
  return hints;
}

/** Validate a declared chat hint before allowing it into a credential form. */
function readCredentialHint({ key, value, field, tokenField }: {
  key: string; value: unknown; field: DeployTargetCredentialSpec["fields"][number]; tokenField: string | undefined;
}, _options = {}): string {
  if (field.secret === true || key === tokenField) throw new ToolInputError({ message: `'${key}' is secret: the person types it into the form, never into the chat.` });
  if (typeof value !== "string") throw new ToolInputError({ message: `'${key}' must be a string.` });
  assertCredentialFreeField({ value, field: key });
  return value;
}

/** The propose-credential form, built from the host's credential spec. Posts back on cancel rather
 *  than closing silently: with the call parked, a silent close would strand the handler for the full
 *  TTL. */
function buildProposeCredentialForm(required: {
  descriptor: DeployTargetDescriptor; credential: DeployTargetCredentialSpec; prefill: Record<string, string>; updating: boolean;
}, _optional = {}): SecretCardForm & { preferredFrameSize: readonly [string, string] } {
  const { descriptor, credential, prefill, updating } = required;
  return {
    title: `Connect ${descriptor.label}`,
    ...(credential.help !== undefined ? { description: credential.help } : {}),
    submitLabel: "Save connection",
    fields: credential.fields.flatMap((field): SecretCardField[] => {
      const base = { kind: "string" as const, name: field.name, label: field.label,
        ...(field.help !== undefined ? { hint: field.help } : {}), required: field.required };
      if (field.secret === true || field.name === credential.tokenField) {
        // The store keeps exact blank secrets on update; the form must permit that submission too.
        const secret: SecretCardField = { ...base, secret: true, required: updating ? false : field.required, allowBlank: updating || !field.required };
        if (updating && !field.required && field.name !== credential.tokenField) {
          return [secret, { kind: "boolean", name: `clear-${field.name}`, label: `Remove ${field.label}`, value: false,
            hint: "Remove the saved value when this connection is saved. Leave unchecked to keep or replace it." }];
        }
        return [secret];
      }
      return [{ ...base, ...(prefill[field.name] !== undefined ? { value: prefill[field.name] } : {}) }];
    }),
    app: { appName: "tovu-deployment-propose-custom-provider-credential", appVersion: "1" },
    preferredFrameSize: ["100%", "560px"],
  };
}

/** Only declared host fields enter the persisted connection; blank secrets keep their prior value. */
function publishConnectionValues({ targetId, credential, values }: {
  targetId: string; credential: DeployTargetCredentialSpec; values: Readonly<Record<string, unknown>>;
}, _optional = {}): Record<string, unknown> {
  const connection: Record<string, unknown> = { providerId: targetId };
  for (const field of credential.fields) {
    // The form submits a blank optional secret as ""; omitted, the store reads it as not provided
    // on create and keeps the stored one on update.
    const blankOptionalSecret = values[field.name] === "" && field.secret === true && !field.required;
    // The explicit remove choice wins over typed text; blank alone still keeps the saved secret.
    if (values[`clear-${field.name}`] === true) {
      connection[field.name] = null;
      continue;
    }
    if (typeof values[field.name] === "string" && !blankOptionalSecret) connection[field.name] = values[field.name];
  }
  return connection;
}

/** An explicit default wins; a sole visible row is also an unambiguous update target. */
function publishCredentialToUpdate({ rows, targetId }: { rows: Awaited<ReturnType<typeof listPublishCredentials>>; targetId: string }, _optional = {}) {
  const candidates = rows.filter(row => row.providerId === targetId);
  return candidates.find(row => row.isDefault) ?? (candidates.length === 1 ? candidates[0] : undefined);
}

/**
 * Saves the submitted form as the host's connection: updates its default or sole visible row,
 * otherwise creates a distinct project key. Only the host's declared
 * fields are forwarded; `publish-credentials/store.ts` is the one place that decides what is valid
 * (the form ships `novalidate`, so this is the real enforcement point). Its messages name fields,
 * never values.
 *
 * @complexity O(n) in the workspace's saved credential count.
 */
async function saveProposedCredential(required: {
  deps: StaticPublishToolDeps; targetId: string; credential: DeployTargetCredentialSpec;
  values: Readonly<Record<string, unknown>>; signal: AbortSignal;
}, _optional = {}): Promise<{ credentialId: string; tokenHint: CredentialTokenHint | null; usedByThisSite: boolean }> {
  const { deps, targetId, credential, values, signal } = required;
  const connection = publishConnectionValues({ targetId, credential, values });
  const repo = abortGuardedCredentialRepo({ store: deps.vendorCredentialSetRepo, signal });
  const writeDeps: PublishCredentialWriteDeps = {
    repo,
    // Only this submitted secret card receives the trusted, grant-checked replacement port.
    allowSharedKeyReplacement: true,
    loadDeployTargets: deployTargetsLoader(deps),
    sealer: deps.siteAssistantSecretSealer,
    keyring: deps.siteAssistantSecretKeyring,
    clock: deps.clock,
    idGen: deps.idGen,
  };
  const saved = await listPublishCredentials(writeDeps, { workspaceId: deps.workspaceId });
  const existing = publishCredentialToUpdate({ rows: saved, targetId });
  // A failed replacement check must leave the working default key intact, before any seal/write.
  if (existing) await checkPublishReplacement({ deps, targetId, credential, connection });
  // Cancellation may arrive during the metadata read or probe; refuse before invoking persistence.
  signal.throwIfAborted();
  const stored = existing
    ? await updatePublishCredential(writeDeps, { workspaceId: deps.workspaceId, id: existing.id, connection })
    : await createPublishCredential(writeDeps, { workspaceId: deps.workspaceId, label: `${CUSTOM_PROVIDER_CREDENTIAL_ROW_LABEL}-${deps.idGen.newId()}`, connection,
      // New project keys stay non-default while the shared save-result path attaches them to this site.
      ...(deps.vendorCredentialSetRepo.project ? { isDefault: false } : {}) });
  return { credentialId: stored.id, tokenHint: stored.tokenHint ?? null, usedByThisSite: existing !== undefined || stored.scope !== "project" };
}

/** Reuse the provider-owned verifier only where replacement would destroy an existing key.
 * @throws PublishCredentialValidationError with fixed copy on refusal/unavailability; preserves legacy hosts without checks.
 * @complexity One registry lookup/load plus one bounded provider check, no persistence.
 */
async function checkPublishReplacement({ deps, targetId, credential, connection }: {
  deps: StaticPublishToolDeps; targetId: string; credential: DeployTargetCredentialSpec; connection: Record<string, unknown>;
}, _options = {}): Promise<void> {
  // A blank secret keeps the stored one (store.ts updatedConnection), so no working key is replaced.
  // A blank OPTIONAL secret is no reason to skip checking a replaced token.
  if (credential.fields.some(field => (field.secret === true && field.required || field.name === credential.tokenField) && !connection[field.name])) return;
  const registry = await deployTargetsLoader(deps)(deps.workspaceId);
  if (!registry.get(targetId)?.module.verifyCredential) return;
  const verification = await verifySubmittedPublishCredential({
    deps: { loadDeployTargets: async () => registry, clock: { nowIso: () => clockNowIso({ clock: deps.clock }) }, fetchFn: deps.fetchFn, observability: deps.observability },
    workspaceId: deps.workspaceId, target: targetId, spec: credential,
    connection: connection as Parameters<typeof verifySubmittedPublishCredential>[0]['connection'],
  });
  if (verification.status === 'valid') return;
  throw new PublishCredentialValidationError(verification.status === 'invalid'
    ? 'This key was refused for this purpose. Nothing was saved. The previous key was kept.'
    : "The service couldn't be reached. Nothing was saved. The previous key was kept.");
}

/**
 * `deployment_propose_custom_provider_credential`'s domain save and post-save probe — kept separate
 * so their cost is measured independently of the engine's exchange lifecycle.
 * @complexity One existing credential write plus an optional provider verification.
 */
async function saveProposeCredential(required: {
  deps: StaticPublishToolDeps; targetId: string; credential: DeployTargetCredentialSpec;
  values: Readonly<Record<string, unknown>>; signal: AbortSignal; locale: string;
}, _optional = {}) {
  const { deps, targetId, locale } = required;
  const saveResult = await saveProposedCredential(required);

  // NEVER echoes a field value, secret or not. Owner 2026-10-07: the submitted human card
  // now authorizes the same post-save read-only check as the admin form. Model-only reads stay probe-free.
  let connection: 'saved' | 'connected' | 'auth' | 'timeout' | 'unreachable' = 'saved';
  try {
    const registry = await deployTargetsLoader(deps)(deps.workspaceId);
    if (saveResult.usedByThisSite && registry.get(targetId)?.module.verifyCredential) {
      const verification = await verifyPublishCredentialById({
        repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer,
        cache: deps.publishCredentialVerificationCache, clock: { nowIso: () => clockNowIso({ clock: deps.clock }) },
        loadDeployTargets: deployTargetsLoader(deps), observability: deps.observability, fetchFn: deps.fetchFn,
      }, { workspaceId: deps.workspaceId, id: saveResult.credentialId });
      connection = credentialConnectionStatus({ verification });
    }
  } catch { connection = 'unreachable'; }
  const hint = formatCredentialHint({ hint: saveResult.tokenHint, locale });
  return { saved: true as const, credentialId: saveResult.credentialId, providerId: targetId, connected: connection === 'connected', connection,
    tokenHint: saveResult.tokenHint, message: `${hint ? hint + '. ' : ''}${credentialText({ id: connection, locale })}` };

}

/** Translate verification into the credential card's existing connection vocabulary. */
function credentialConnectionStatus({ verification }: {
  verification: Awaited<ReturnType<typeof verifyPublishCredentialById>>;
}, _options = {}): 'connected' | 'auth' | 'timeout' | 'unreachable' {
  if (verification?.status === 'valid') return 'connected';
  if (verification?.status === 'invalid') return 'auth';
  return verification?.message === credentialText({ id: 'timeout' }) ? 'timeout' : 'unreachable';
}

/** All blocked assistant publishes report the same event and product source. */
function trackBlockedToolPublish({ deps, principalId, target, reasonClass }: { deps: StaticPublishToolDeps; principalId: string; target: string; reasonClass: "config" | "consent" | "busy" }, _options = {}): void {
  deps.tracker?.capture({ name: "site_publish_blocked", userId: principalId }, { properties: { target, reasonClass, source: "assistant" } });
}

/**
 * Builds this domain's `ToolRegistration[]` — the same shape every other domain's
 * `build<Domain>Registrations` produces (see e.g. `recovery/tool-registrations.ts`'s
 * `buildRecoveryRegistrations`). Called by `assistant/tool-registrations.ts`, which imports
 * `buildStaticPublishRegistrations`/`staticPublishDerivedRisk` from this file and lists them as
 * their own `"static-publish"` entry in `DOMAIN_SLICES` — see that file's own comment on that entry
 * for why static-publish stays a separate slice rather than folding into this directory's sibling
 * `deployments`/`agent-tools.ts` slice.
 *
 * @param deps - `StaticPublishToolDeps` plus this file's own test-only overrides (`credentialSource`,
 *   `buildTarget`). `credentialSource` defaults to the same DB-first, env-fallback-only-in-
 *   `"self-hosted-cli"`-mode composition `publish-site.ts`'s route constructs.
 * @param surfaces - The held-open confirmation exchange store `deployment_execute_static_publish`
 *   parks on — see this file's header. Required, matching `buildPostRegistrations`' own shape (the
 *   other domain whose gate needs this), since a domain with no store at all could never wire this
 *   tool's gate at all.
 * @complexity O(1) registration-time cost; each wired handler's own cost is documented at its call
 *   site above (preview/capabilities: O(1) plus the provider count; execute: one `exportSite` pass
 *   plus one provider API call, only after a human confirms).
 */
/** Bind publish credential saving to its existing descriptor, permission and sealed-store owner.
 * @param required - Existing publish dependencies and shared surface exchanges.
 * @returns An internal save adapter, never a retired tool registration.
 * @example buildPublishHostCredentialHandler({ deps, surfaces });
 * @complexity O(1) binding; invocation reads the provider registry and saved credential summaries.
 */
export function buildPublishHostCredentialHandler({ deps, surfaces }: { deps: StaticPublishToolDeps; surfaces: AssistantSurfaceDeps }, _optional = {}): ToolHandler {
  return async (ctx, optional = {}) => {
      const raw = requireInputRecord({ input: ctx.input });
      const { descriptor, credential } = requireCredentialTarget(raw, await deployTargetsLoader(deps)(deps.workspaceId));
      const prefill = readCredentialHints(raw, descriptor);

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.credentials.write" }, { entityType: SITE_PUBLISH_ENTITY });

      // Fail closed rather than degrade — identical posture to the execute-publish guard above.
      // The engine supplies a ToolInputError so the refusal remains caller-safe through transport.
      const stored = await listPublishCredentials({ repo: deps.vendorCredentialSetRepo, loadDeployTargets: deployTargetsLoader(deps) }, { workspaceId: deps.workspaceId });
      const updating = publishCredentialToUpdate({ rows: stored, targetId: descriptor.id }) !== undefined;
      const locale = await resolveOperatorLocale({ deps, workspaceId: deps.workspaceId, principalId: ctx.principal.id });
      const pluginCard = await findPluginCredentialCard({ loadCards: deps.loadPluginCredentialCards, workspaceId: deps.workspaceId, saveKind: 'publish-host', target: descriptor.id });
      const card = defineSecretCardTool<{
        descriptor: DeployTargetDescriptor; credential: DeployTargetCredentialSpec; prefill: Record<string, string>; updating: boolean; locale: string;
      }, Awaited<ReturnType<typeof saveProposeCredential>>, Awaited<ReturnType<typeof saveProposeCredential>> | {
        saved: false; cancelled: boolean; reason?: string; message?: string; note?: string;
      }>({
        toolId: CREDENTIAL_SAVE_TOOL_ID,
        prepare: async () => ({ descriptor, credential, prefill, updating, locale }),
        // New project keys need explicit attachment; an update changes the saved row where it lives.
        form: ({ prep }) => applyPluginCredentialCard({ card: pluginCard, form: buildProposeCredentialForm(prep) }),
        save: ({ values, prep, signal }) => saveProposeCredential({ deps, targetId: prep.descriptor.id, credential: prep.credential, values, signal, locale: prep.locale }),
        result: ({ prep, run }) => {
          if (run.status === 'saved') return run.saved;
          if (run.status === 'cancelled') return { saved: false, cancelled: true };
          if (run.status === 'blank' || run.status === 'failed') return { saved: false, cancelled: false, reason: 'invalid',
            message: run.status === 'blank' ? credentialText({ id: 'blank', locale: prep.locale }) : run.safeMessage };
          return { saved: false, cancelled: false, reason: run.status,
            note: run.status === 'expired' ? "The user did not respond to the credential form before it expired. Nothing was saved." : "The credential form was closed because the run ended. Nothing was saved." };
        },
        outcome: ({ prep, run }) => {
          if (run.status === 'cancelled' || run.status === 'expired' || run.status === 'abandoned') return undefined;
          const saved = run.status === 'saved';
          let message: string;
          if (run.status === 'saved') message = run.saved.message;
          else if (run.status === 'blank') message = credentialText({ id: 'blank', locale: prep.locale });
          else if (run.status === 'failed') message = run.safeMessage;
          else message = credentialText({ id: 'unreachable', locale: prep.locale });
          return { title: credentialText({ id: saved ? 'savedTitle' : 'unreachable', locale: prep.locale }), state: saved ? 'success' : 'failure', message };
        },
      }, {
        uriHost: 'tovu',
        text: { noEmitter: "deployment_propose_custom_provider_credential: this execution context has no interactive confirmation channel " +
          "(no emitSurface), so a credential form cannot be shown here. Nothing was saved.", saveFailure: credentialText({ id: 'unreachable', locale }) },
        safeError: err => {
          if (err instanceof PublishCredentialDuplicateLabelError) return err.message;
          return err instanceof PublishCredentialValidationError ? translateCredentialMessage({ message: err.message, locale }) : undefined;
        },
        logFailure: metadata => console.warn(JSON.stringify(metadata)),
      });
      return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, optional);
  };
}

/** A host lacking a saved key on this site. `worksForIds` is non-empty only for a host that is not
 *  loaded (its plugin is off): the copy inventory derives `publishHosts` from this site's LOADED
 *  hosts, so an off host never appears there (2026-11-02 owner bug: with Vercel off, the chat said
 *  "no site has a Vercel key" while 8 sites held one). For such a host a key's saved worksFor (the
 *  host id or its vendor id, the ids the Jini matcher reads) declares compatibility. Presence only:
 *  the copy card and the publish itself still re-check the key. */
interface MissingHost { readonly id: string; readonly worksForIds: readonly string[] }

function hostsMissingSavedKey({ providers, installed }: {
  providers: readonly { providerId: string; executable: boolean; savedCredentials: readonly unknown[] | null }[];
  installed: readonly InstalledDeployTarget[];
}, _options = {}): MissingHost[] {
  return providers.filter(provider => !provider.savedCredentials?.length).map(provider => {
    if (provider.executable) return { id: provider.providerId, worksForIds: [] };
    const vendorId = installed.find(item => item.descriptor.id === provider.providerId)?.descriptor.credential?.vendorId;
    return { id: provider.providerId, worksForIds: [provider.providerId, vendorId].filter((id): id is string => !!id).map(id => id.toLowerCase()) };
  });
}

// Cross-site discovery used to offer another site's key for a missing host. That reveals private
// inventory to a site agent. Offer the owner picker instead; the model never receives its choices.
export function buildStaticPublishRegistrations(deps: StaticPublishToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const credentialSource =
    deps.credentialSource ??
    composePublishCredentialSource({
      workspaceId: deps.workspaceId,
      executionMode: deps.publishExecutionMode,
      dbDeps: { repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer, loadDeployTargets: deployTargetsLoader(deps) },
    });
  const historyStore = deps.historyStore ?? deps.publishHistoryStore;

  const handlers: Record<string, ToolHandler> = {
    deployment_preview_static_publish: async (ctx) => {
      const raw = requireInputRecord({ input: ctx.input });
      const registry = await deployTargetsLoader(deps)(deps.workspaceId);
      const loaded = requireStaticPublishTarget(raw, registry);
      const target = loaded.descriptor.id;

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: DEPLOYMENTS_READ_PERMISSION }, { entityType: SITE_PUBLISH_ENTITY });

      const { config, plan } = planToolPublish(registry, raw, loaded);
      const validationError = plan.ok ? null : plan.message;
      const basePath = plan.ok ? plan.basePath : undefined;
      // Local readiness stays non-decrypting. A provider inspection below is an explicit
      // authenticated read; its server-side credential never enters this tool result.
      const credential = await credentialSource.isConfigured({ workspaceId: deps.workspaceId, target, ...toolCredentialChoice({ raw }) });

      const inspected = plan.ok && credential.configured ? await inspectStaticPublish({
        deps: { credentialSource, loadDeployTargets: deps.loadDeployTargets, tracker: deps.tracker, observability: deps.observability, hostKit: deps.hostKit, formDestination: deps.formDestination },
        input: { workspaceId: deps.workspaceId, config, projectName: typeof raw.projectName === "string" ? raw.projectName : "",
          ...toolCredentialChoice({ raw }) },
      }) : {};
      return { ...buildStaticPublishPreviewResult(target, validationError, basePath, credential),
        ...(inspected.inspection ? { providerInspection: inspected.inspection } : {}) };
    },

    /**
     * Never decrypts — reads through `listPublishCredentials` (a pure DB read of
     * `vendor_credential_sets`; see its own "read model only" doc) and `credentialSource.isConfigured`
     * (this file's own preview handler already relies on the identical never-decrypting contract).
     * Structurally cannot reach `resolveForPublish`/`resolveDefaultForPublish`: this handler never
     * hands them a `SecretSealerPort`. `tokenTail` is the stored last 4 characters, never derived by
     * decrypting.
     */
    deployment_get_static_publish_capabilities: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: DEPLOYMENTS_READ_PERMISSION }, { entityType: SITE_PUBLISH_ENTITY });

      const loadDeployTargets = deployTargetsLoader(deps);
      // Owner policy: unseal only server-side to derive the safe hint.
      // Readiness still uses isConfigured(); no usable credential or provider probe reaches this result.
      const saved = await listPublishCredentials({ repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer, loadDeployTargets } satisfies PublishCredentialReadDeps, {
        workspaceId: deps.workspaceId,
      });

      const registry = await loadDeployTargets(deps.workspaceId);
      const providerCapabilityContext: ProviderCapabilityContext = { deps, credentialSource, historyStore, saved };
      const inventory = deps.loadInstalledDeployTargets
        ? await deps.loadInstalledDeployTargets({ workspaceId: deps.workspaceId })
        : { items: registry.list().map(({ descriptor, pluginId }) => ({ descriptor, pluginId, enabled: true })), refusals: [] };
      const providers = await Promise.all(inventory.items.map(installed => buildInstalledProviderCapability({ installed, registry, context: providerCapabilityContext })));
      const refusals = [...new Set([...inventory.refusals, ...registry.refusals])];

      const missing = hostsMissingSavedKey({ providers, installed: inventory.items });
      if (missing.length) return { executionMode: deps.publishExecutionMode, providers, refusals,
        credentialSetup: deps.vendorCredentialSetRepo.project
          ? { toolId: "credential_copy_from_project", message: "Use a saved key to choose from Shared Keys, or enter a new key in the secure card." }
          : { toolId: "credential_save", kind: "publish-host", message: "Open the secure key card to save a publishing key for this site." } };
      return { executionMode: deps.publishExecutionMode, providers, refusals };
    },

    /** Permission-checked job reads; no credentials or provider requests on the polling path. */
    deployment_get_static_publish_status: async (ctx) => {
      const raw = requireInputRecord({ input: ctx.input ?? {} });
      for (const key of Object.keys(raw)) if (key !== "jobId" && key !== "executionId") throw new ToolInputError({ message: `Unknown publish-status field '${key}'. Pass jobId or executionId, or {} for this site's latest publish.` });
      const jobId = raw.jobId === undefined ? undefined : requireString({ input: raw, key: "jobId" });
      const requestId = raw.executionId === undefined ? undefined : requireString({ input: raw, key: "executionId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: DEPLOYMENTS_READ_PERMISSION }, { entityType: SITE_PUBLISH_ENTITY });
      const snapshot = getPublishJobSnapshot({ workspaceId: deps.workspaceId, jobId, requestId });
      if (!snapshot) return { code: "PUBLISH_JOB_NOT_FOUND", message: "No retained publish job was found for this site. A restart clears job snapshots. Check the hosting dashboard before starting another publish." };
      const mapped = snapshot.result ? mapPublishOutcomeToToolResult(snapshot.result, { id: snapshot.jobId }, { target: snapshot.target }, [], "") : undefined;
      return { ...snapshot, ...(mapped ? { result: mapped.result } : {}),
        message: publishJobRecoveryMessage({ job: snapshot, statusToolId: "deployment_get_static_publish_status" }) };
    },

    /** Validates and starts the existing background publish path after approval. The job owns
     * its lifetime; the initiating delegated call can finish or be cancelled independently. */
    deployment_execute_static_publish: async (inputCtx, optional = {}) => {
      // Keep the same detached proposal/actor snapshot the former policy wrapper supplied before
      // any asynchronous registry or permission read; later cards and effects use only this call.
      const ctx = { ...inputCtx, input: structuredClone(inputCtx.input), principal: { ...inputCtx.principal }, run: { ...inputCtx.run } };
      const raw = requireInputRecord({ input: ctx.input });
      const registry = await deployTargetsLoader(deps)(deps.workspaceId);
      const loaded = requireStaticPublishTarget(raw, registry);
      const target = loaded.descriptor.id;
      const projectName = requireString({ input: raw, key: "projectName" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.publish" }, { entityType: SITE_PUBLISH_ENTITY });

      const { config, plan } = planToolPublish(registry, raw, loaded);
      if (!plan.ok) {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "config" });
        throw new ToolInputError({ message: `deployment_execute_static_publish: ${plan.message}` });
      }
      const consent = await checkToolPublishConsent({ deps, principalId: ctx.principal.id });
      if (consent) {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "consent" });
        return { published: false, cancelled: false, ...consent };
      }

      const onSettled = () => {
        const settled = getPublishJobSnapshot({ workspaceId: deps.workspaceId, requestId: ctx.executionId });
        if (settled?.result && optional.emitSurface) {
          const mapped = mapPublishOutcomeToToolResult(settled.result, { id: settled.jobId }, config, [], "");
          void optional.emitSurface(mapped.outcome).catch(() => console.warn("[static-publish] result card could not be delivered; read deployment_get_static_publish_status for the result"));
        }
      };
      if (config.customDomain && loaded.module.preview) {
        return domainPublishTool({ deps, surfaces, credentialSource, historyStore, config, projectName, onSettled,
          ...toolCredentialChoice({ raw }) })(ctx, optional);
      }

      // Never decrypts (same `isConfigured()` contract the preview/capabilities handlers use above).
      // Refuse unavailable credentials before starting an export.
      const readiness = await credentialSource.isConfigured({ workspaceId: deps.workspaceId, target, ...toolCredentialChoice({ raw }) });
      if (!readiness.configured) {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "config" });
        return {
          published: false,
          cancelled: false,
          reason: "no-credential",
          credentialSetup: issueCredentialSetup({ setupToolId: "credential_save", prefill: { kind: "publish-host", target } }, {}),
          message: `No publish credential is configured for '${target}'. Call credential_save with kind publish-host to open its secure card, then retry once. The admin's Static Site tab is an alternative. (${readiness.reason})`,
        };
      }

      if (ctx.signal.aborted) return { published: false, cancelled: false, reason: "abandoned" };

      // This domain owns one approval: the detailed domain plan above, or the ordinary publish
      // card below. A second registration wrapper would ask twice for a domain publication.
      return humanConfirmedToolHandler(surfaces, {
        flag: 'published',
        prepare: async () => toolApprovalConfirmation({ descriptor: { id: 'deployment_execute_static_publish', metadata: toolMetadata.deployment_execute_static_publish, inputSchema: EXECUTE_STATIC_PUBLISH_SCHEMA },
          input: raw, locale: await resolveOperatorLocale({ deps, workspaceId: deps.workspaceId, principalId: ctx.principal.id }) }),
        dialog: spec => spec,
        run: async (approvedCtx) => {
          await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: approvedCtx.principal.id, permission: "deployments.publish" }, { entityType: SITE_PUBLISH_ENTITY });
          const currentConsent = await checkToolPublishConsent({ deps, principalId: approvedCtx.principal.id });
          if (currentConsent) {
            trackBlockedToolPublish({ deps, principalId: approvedCtx.principal.id, target, reasonClass: "consent" });
            return { published: false, cancelled: false, ...currentConsent };
          }
          if (approvedCtx.signal.aborted) return { published: false, cancelled: false, reason: "abandoned" };
          const active = getPublishRunSnapshot();
          if (active.status === "running") {
            trackBlockedToolPublish({ deps, principalId: approvedCtx.principal.id, target, reasonClass: "busy" });
            return { published: false, cancelled: false, code: "ALREADY_RUNNING", jobId: getPublishJobSnapshot({ workspaceId: deps.workspaceId, jobId: active.jobId! })?.jobId, message: "A publish is already running. Call deployment_get_static_publish_status with this jobId (or {} for the latest job on this site). Do not start another publish." };
          }
          const job = startPublishRun(
            { credentialSource, loadDeployTargets: deployTargetsLoader(deps), buildTarget: deps.buildTarget, tracker: deps.tracker, observability: deps.observability, hostKit: deps.hostKit, formDestination: deps.formDestination, publicPageSecurityHeaders: deps.publicPageSecurityHeaders, pluginExportHosts: deps.pluginExportHosts },
            { requestId: approvedCtx.executionId, productEvent: { userId: approvedCtx.principal.id, source: "assistant" }, workspaceId: deps.workspaceId, publishOutputRootDir: deps.publishOutputRootDir, idGen: deps.idGen, exportSiteBound: deps.exportSiteBound, config, projectName,
              ...toolCredentialChoice({ raw }) },
            { nowIso: () => clockNowIso({ clock: deps.clock }) },
            historyStore,
            { triggeredBy: "agent_tool", onSettled },
          );
          return { published: false, accepted: true, jobId: job.jobId, status: job.status, progress: job.progress,
            message: "Publish started in the background. Call deployment_get_static_publish_status with this jobId in 5 seconds for progress and the final result. Do not publish again while it is running." };
        },
      })(ctx, optional);
    },

    /**
     * The MCP-UI form-gated credential save for any host whose plugin declares a credential. Same
     * Opens an exchange, emits a form, then uses `askThenReport` to replace it with the real save
     * outcome: the model proposes structure for a human to fill in.
     *
     * The schema has no secret property, and a secret or undeclared field is refused before any form
     * is raised. The human's typed secret lands in `answer.params` server-side and is sealed by
     * `publish-credentials/store.ts`; it never enters a prompt or a completion, and the result never
     * echoes any field.
     */
    /**
     * Pure read — the host plugin module's own `hostingSetup` over the caller's non-secret credential
     * fields (never a saved credential). A host with no such steps is refused with the reason.
     */
    deployment_generate_bucket_hosting_setup: async (ctx) => {
      const raw = requireInputRecord({ input: ctx.input });
      const loaded = requireStaticPublishTarget(raw, await deployTargetsLoader(deps)(deps.workspaceId));
      const { descriptor, module } = loaded;
      if (module.hostingSetup === undefined) throw new ToolInputError({ message: `${descriptor.id} has no hosting-setup steps: publishing to it serves the site.` });
      const fields = readCredentialHints(raw, descriptor);

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: DEPLOYMENTS_READ_PERMISSION }, { entityType: SITE_PUBLISH_ENTITY });

      try {
        return module.hostingSetup({ fields });
      } catch (err) {
        throw new ToolInputError({ message: err instanceof Error ? err.message : String(err) });
      }
    },
  };

  // No `unwiredToolIds`: this domain now wires its ENTIRE catalog, same tripwire discipline as
  // Posts/Pages/Forms/Entries/Widgets — a 4th catalog entry added without a handler fails the build.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "static-publish",
    catalogModule: "features/deployments/publish-agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: staticPublishDerivedRisk,
  });
}

/**
 * Contributes Static Publish's AI tools; called once by the composition root's
 * `installFirstPartyToolContributors()`, never as an import side effect.
 * See ./tool-registrations.ts for the shared deployments/credential dependency boundary.
 */
export function contributeStaticPublishTools(): ToolContributor<StaticPublishToolDeps, AssistantSurfaceDeps> {
  return { domain: "static-publish", build: buildStaticPublishRegistrations, risk: staticPublishDerivedRisk };
}

import { ToolInputError, type ToolHandler } from '@jini-ai/core';
import { nowIso } from '@jini-ai/core/primitives';
import { requireToolPermission, adaptLegacyAuthorize } from '@jini-ai/cms/core';
import type { AssistantSurfaceDeps } from '@jini-ai/daemon/surface-exchanges';
import { humanConfirmedToolHandler } from '#src/contracts/core/human-confirm';
import { plan, confirm, execute, PlanStaleError, ForbiddenError, type GatedMutationHooks, type GatewayDeps } from '#src/contracts/core/gated-mutations/gateway';
import { TokenExpiredError, TokenAlreadyRedeemedError } from '#src/contracts/core/gated-mutations/token';
import { planHashOf, resolveActorClassIdentity } from '#src/contracts/core/gated-mutations/composition';
import type { StaticPublishToolDeps } from '../publish-tool-deps.js';
import type { StaticPublishConfig, PublishCredentialSource } from './types.js';
import { inspectStaticPublish, type StaticPublishInspection } from './inspection.js';
import { getPublishRunSnapshot, startPublishRun, type PublishRunSnapshot } from './publish-run.js';
import { domainPublishRows } from './domain-publish-rows.js';
import type { PublishHistoryStore } from './publish-history.js';
import { checkToolPublishConsent } from './publish-consent.js';

interface DomainPublishDetails extends StaticPublishInspection {
  readonly workspaceId: string;
  readonly actorId: string;
  readonly config: StaticPublishConfig;
  readonly projectName: string;
}

/** CMS wiring only: the existing gateway owns authorization/token/hash/single-use semantics;
 * the existing human exchange owns consent. Nothing in a model request can create this capability.
 * No new approval store, domain ledger, journal or automatic rollback is introduced. */
export function domainPublishTool(required: {
  deps: StaticPublishToolDeps;
  surfaces: AssistantSurfaceDeps;
  credentialSource: PublishCredentialSource;
  historyStore: PublishHistoryStore;
  config: StaticPublishConfig;
  projectName: string;
  credentialId?: string;
  onSettled?: () => void;
}, _options = {}): ToolHandler {
  const { deps, surfaces, config, projectName } = required;
  const gateway = deps.gatedMutations?.gatewayDeps;
  if (!gateway) throw new ToolInputError({ message: 'DOMAIN_APPROVAL_UNAVAILABLE: The shared mutation gateway is not configured. Contact the installation owner; no domain changes were made.' });
  return humanConfirmedToolHandler(surfaces, {
    flag: 'published',
    prepare: async ctx => {
      const hooks = makeHooks({ ...required, gateway, actorId: ctx.principal.id, signal: ctx.signal, requestId: ctx.executionId });
      const planned = await plan({ deps: gateway, principalId: ctx.principal.id, principalKind: 'agent', hooks });
      const details = planned.details as DomainPublishDetails;
      return { hooks, planned, details };
    },
    dialog: ({ details }) => ({
      toolId: 'deployment_execute_static_publish', errorCode: 'DOMAIN_PUBLISH', title: 'Publish and change these domain bindings?',
      details: domainPublishRows({ inspection: details.inspection!, projectName, target: config.target }),
      warning: 'The listed records, bindings and whole overlapping routes will be changed. This can interrupt the existing site and other hosts covered by wildcard routes. Mail, TXT and CAA stay unchanged. There is no automatic rollback. Cancel to keep everything as it is.',
      danger: true, confirmLabel: 'Publish and apply these changes',
    }),
    run: async (ctx, { hooks, planned }, confirmer) => {
      const consent = await checkToolPublishConsent({ deps, principalId: ctx.principal.id });
      if (consent) {
        deps.tracker?.capture({ name: 'site_publish_blocked', userId: ctx.principal.id }, { properties: { target: config.target, reasonClass: 'consent', source: 'assistant' } });
        return { published: false, cancelled: false, ...consent };
      }
      const token = await confirm({ deps: gateway, principalId: confirmer.id, principalKind: confirmer.kind, hooks, planId: planned.planId, planHash: planned.planHash });
      const result = await executeDomainPublish({ gateway, principalId: ctx.principal.id, hooks, confirmationToken: token.confirmationToken });
      return { accepted: true, published: false, jobId: result.jobId, status: result.status, progress: result.progress,
        message: 'Publish started after domain approval. Call deployment_get_static_publish_status with this jobId in 5 seconds for progress and the final result. Do not publish again while it is running.' };
    },
  });
}

/** Preserve typed gateway refusals through the tool transport's caller-safe error channel. */
async function executeDomainPublish(required: {
  gateway: GatewayDeps; principalId: string; hooks: GatedMutationHooks<DomainPublishDetails, PublishRunSnapshot>; confirmationToken: string;
}, _options = {}): Promise<PublishRunSnapshot> {
  try { return await execute({ deps: required.gateway, principalId: required.principalId, principalKind: 'agent', hooks: required.hooks, confirmationToken: required.confirmationToken }); }
  catch (error) {
    if (error instanceof PlanStaleError) throw new ToolInputError({ message: 'DOMAIN_PLAN_STALE: Infrastructure or the connection changed after review. Preview and confirm the current state; no publish or domain changes were started.' });
    if (error instanceof TokenExpiredError) throw new ToolInputError({ message: 'DOMAIN_APPROVAL_EXPIRED: The domain approval expired. Preview and confirm again.' });
    if (error instanceof TokenAlreadyRedeemedError) throw new ToolInputError({ message: 'DOMAIN_APPROVAL_ALREADY_USED: This approval was already used. Inspect the last publish and preview again.' });
    if (error instanceof ForbiddenError) throw new ToolInputError({ message: 'DOMAIN_APPROVAL_FORBIDDEN: Permission or the approving person changed. Ask the installation owner to restore access, then preview again.' });
    throw error;
  }
}

function makeHooks(required: {
  deps: StaticPublishToolDeps; gateway: GatewayDeps; surfaces: AssistantSurfaceDeps;
  credentialSource: PublishCredentialSource; historyStore: PublishHistoryStore;
  config: StaticPublishConfig; projectName: string; credentialId?: string; onSettled?: () => void; actorId: string; signal: AbortSignal; requestId: string;
}, _options = {}): GatedMutationHooks<DomainPublishDetails, PublishRunSnapshot> {
  const { deps, credentialSource, historyStore, config, projectName, actorId, signal } = required;
  const expiresAt = Date.parse(nowIso({ clock: deps.clock })) + 600_000;
  return {
    domain: 'deployment.static-publish-domain', scopeId: deps.workspaceId, readPermission: 'deployments.read', mutatePermission: 'deployments.publish',
    resolveActorClassIdentity,
    computePlan: async () => {
      const inspected = await inspectStaticPublish({ deps: { credentialSource, loadDeployTargets: deps.loadDeployTargets, tracker: deps.tracker, observability: deps.observability, hostKit: deps.hostKit, formDestination: deps.formDestination },
        input: { workspaceId: deps.workspaceId, config, projectName, ...(required.credentialId ? { credentialId: required.credentialId } : {}) } });
      if (inspected.inspection?.domains?.inventoryStatus !== 'complete') throw new ToolInputError({ message: `DOMAIN_INVENTORY_UNKNOWN: ${inspected.inspection?.domains?.message ?? 'Complete authenticated domain inspection is required. Preview again.'}` });
      const details = { ...inspected, workspaceId: deps.workspaceId, actorId, config, projectName };
      return { details, planHash: inspectionPlanHash({ details }) };
    },
    executeMutation: async ({ details }) => {
      signal.throwIfAborted();
      if (getPublishRunSnapshot().status === 'running') throw new ToolInputError({ message: 'ALREADY_RUNNING: A publish is running. Wait for it to finish, then preview again.' });
      const domainPlan = details.inspection!.domains!;
      return startPublishRun({ credentialSource, loadDeployTargets: deps.loadDeployTargets, tracker: deps.tracker, observability: deps.observability, hostKit: deps.hostKit, formDestination: deps.formDestination, publicPageSecurityHeaders: deps.publicPageSecurityHeaders, pluginExportHosts: deps.pluginExportHosts }, {
        requestId: required.requestId, productEvent: { userId: actorId, source: "assistant" }, workspaceId: deps.workspaceId, publishOutputRootDir: deps.publishOutputRootDir, idGen: deps.idGen, exportSiteBound: deps.exportSiteBound,
        config, projectName, ...(details.credentialId ? { credentialId: details.credentialId } : {}),
        domainApproval: { plan: domainPlan, credentialBinding: details.credentialBinding!, authorize: async ({ fingerprint }) => {
          // The approved background job outlives the initiating call. Recheck permission and
          // approval expiry here; cancelling that call after enqueue does not revoke this job.
          await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: actorId, permission: 'deployments.publish' });
          return fingerprint === domainPlan.fingerprint && Date.parse(nowIso({ clock: deps.clock })) <= expiresAt;
        } },
      }, { nowIso: () => nowIso({ clock: deps.clock }) }, historyStore, { triggeredBy: "agent_tool", ...(required.onSettled ? { onSettled: required.onSettled } : {}) });
    },
  };
}

/** The plugin fingerprint binds exact inventory and operations canonically. Preserve that contract:
 * response ordering alone must not invalidate a human's consent at the shared gateway. */
function inspectionPlanHash({ details }: { details: DomainPublishDetails }, _options = {}): string {
  const inspected = details.inspection!;
  return planHashOf({ ...details, inspection: { resourceName: inspected.resourceName, targetId: inspected.targetId,
    hostingChanges: inspected.hostingChanges, domainFingerprint: inspected.domains!.fingerprint } });
}

import { redactSecretShapes } from "@tovu/contracts/secret-redaction";
import { createPublishJobStore, type PublishJobSnapshot, type DeployPublishProgress } from "@jini-ai/devops/deploy";
import { publishStaticSite, type StaticPublishDeps, type StaticPublishInput } from "./adapter.js";
import type { PublishHistoryEntry, PublishHistoryStore, PublishTrigger } from "./publish-history.js";
import { publicPublishConfigFields } from "./publish-history.js";
import type { StaticPublishOutcome, StaticPublishTargetId } from "./types.js";

/**
 * @file This sub-feature's process-local single-flight state for a real publish, extracted out of
 * `server/routes/admin/system/publish-site.ts` (2026-08-16, Terra audit finding #1) so a SECOND
 * caller — `deployment_execute_static_publish` (`publish-agent-tools.ts`, the assistant's
 * MCP-UI-confirmed publish tool) — can share the exact same guard the admin route's own trigger
 * already enforced, instead of calling {@link publishStaticSite} directly with no tracking at all.
 *
 * Before this file existed, `publish-site.ts` held its own PRIVATE `currentRun` module variable and
 * checked it before every trigger; `publish-agent-tools.ts` had no equivalent slot to check at all
 * (not merely a bug in its own guard — there was structurally nothing for it to check, since the
 * state lived un-exported in a `src/server/**` file this domain must never import from — see this
 * module's placement note below). Two publishes to the same or even different targets both run a
 * fresh `clean` export into a shared per-target output directory (`adapter.ts`'s `publishOutputDir`);
 * a human clicking "Publish" in the admin UI at the same moment an agent's confirmed
 * `deployment_execute_static_publish` call reached its own `publishStaticSite` invocation could
 * clean and rewrite the same directory out from under each other. This became reachable the day
 * `deployment_execute_static_publish` went from unwired to a real, agent-callable tool.
 *
 * Lives in `static-publish/`, not this domain's sibling `features/deployments/export-run.ts` — a
 * DIFFERENT sub-feature (this file's own imports are `static-publish/adapter.ts`'s `publishStaticSite`
 * only, never `#src/features/site-export/index`), but the SAME reasoning `export-run.ts`'s header gives for its own
 * placement applies here too: `server/routes/admin/system/publish-site.ts` (a `src/server/**` file)
 * is free to import FROM this domain, but `publish-agent-tools.ts`'s own `tool-registrations.ts`-style
 * rule (see `deployments/tool-registrations.ts`'s file header) forbids the reverse — a domain's
 * tool-wiring file must never import from `src/server/**`. Putting the shared slot here, not there,
 * is what lets both callers import ONE real module without either one crossing that back-edge.
 *
 * DISCLOSED CROSS-PROCESS GAP, same shape `export-run.ts`'s own header already discloses for its own
 * `currentRun`: this module's publish-job store is process-local, single-flight-correct only
 * WITHIN one OS process. Tovu's admin HTTP server and the standalone agent daemon
 * (`assistant/agent-daemon-server.ts`) each load their own independent copy of this module — there is
 * no cross-process lock, and this file does not attempt to add one (that is a design change, e.g. a
 * lockfile under the publish output directory or routing the daemon's call back over HTTP to the main
 * process — out of scope for this fix, which closes the WITHIN-process gap only). The in-process BYOK
 * execution mode (`server/modules/assistant-byok.ts`, composing the same tool catalog inside the main
 * server process) shares this exact module instance with the admin HTTP route, so single-flight holds
 * there — which is the concrete scenario this fix closes (a human using the admin UI's Static Site tab
 * and the assistant dock in the SAME running server, at the same time).
 *
 * ## Publish history (2026-08-16, Defect 2; reworked same day into an append-only DB table)
 *
 * The SAME reason this module exists in the first place — one shared slot both `publish-site.ts`'s
 * HTTP trigger route and `deployment_execute_static_publish` settle through — is why publish HISTORY
 * is also recorded here rather than in either caller: recording it once, at the one place both routes
 * already converge, means neither call site needs to change to gain it. `settleWithOutcome`/
 * `settleWithError` above are this module's PRE-EXISTING job (the single-flight snapshot); recording
 * history is a separate, additional side effect performed alongside them, not folded into them, so a
 * reader auditing "what does settling a run do to the shared snapshot" is not also reading unrelated
 * persistence code. See `./publish-history.ts`'s own header for the storage design (an append-only
 * `publish_history` table, `src/platform/db/schema.sqlite.ts`; migration `0043`).
 *
 * `historyStore` is a REQUIRED parameter on {@link startPublishRun} — deliberately no module-level default the way this file's original
 * (file-backed) design had one. A DB-backed store needs a live `ContentDb` handle to construct, and
 * only the composition root (`server/deps.ts`/`server/app.ts`) has one; a module-level singleton
 * constructed at import time cannot get one without either module-load-time I/O (this module's own
 * prior header explicitly avoided that) or a global mutable setter (a worse shape than just requiring
 * the argument). Both real callers thread it from `RouteDeps.publishHistoryStore` — `publish-site.ts`
 * passes `deps.publishHistoryStore` straight through; `publish-agent-tools.ts`'s
 * `StaticPublishToolDeps` does the same, with its own `historyStore` field staying a TEST-ONLY
 * override on top (see that file's own doc). Every test in `publish-run.unit.test.ts` already passes
 * an explicit `InMemoryPublishHistoryStore`, so this change needed no test-signature updates.
 *
 * `toHistoryEntry` below also decides `triggeredBy` (`'admin_ui'` vs `'agent_tool'`) — not a
 * caller-supplied field, but a trigger bound by each caller of {@link startPublishRun}
 * when it calls {@link recordHistoryIfPublished}, since which function ran IS the answer
 * (see `publish-history.ts`'s own `PublishTrigger` doc).
 */

export type PublishRunStatus = "idle" | "running" | "completed" | "errored";

export interface PublishRunSnapshot {
  readonly jobId?: string;
  readonly requestId?: string;
  readonly progress?: DeployPublishProgress;
  status: PublishRunStatus;
  startedAtIso: string | null;
  finishedAtIso: string | null;
  target: StaticPublishTargetId | null;
  /** Present only once `status` is `"completed"` or `"errored"` AND the run reached a real outcome
   *  (an unexpected throw out of `publishStaticSite` populates `error` instead). */
  result?: StaticPublishOutcome;
  /** Populated only when the run settled via an unexpected throw rather than a normal
   *  `StaticPublishOutcome` — a message, never the raw error object, same boundary
   *  `export-run.ts`'s own `error` field crosses. */
  error?: string;
}

const IDLE_RUN: PublishRunSnapshot = { status: "idle", startedAtIso: null, finishedAtIso: null, target: null };

/** Process-local job store — see this file's header for exactly which callers share ONE instance
 *  of it and which do not. */
const publishJobs = createPublishJobStore<StaticPublishOutcome>({});

/**
 * Maps a settled `outcome` into the durable record this run's publish produced — `undefined` when
 * nothing was actually published (`outcome.ok === false`; see {@link PublishHistoryEntry}'s own doc
 * on why a failure is never recorded at all, not recorded-as-failed). `owner`/`repo`/`branch`/
 * `commitSha` are the HOST's own facts, read off `outcome.providerMetadata` (whatever the target
 * module reports, string values only) — never off `input.config`, and never by naming a target here.
 * `deploymentId` is always carried through when the outcome has one.
 *
 * @complexity O(1) — fixed-shape field mapping, no iteration.
 */
function toHistoryEntry(
  input: StaticPublishInput,
  outcome: StaticPublishOutcome,
  clock: { nowIso(): string },
  triggeredBy: PublishTrigger
): PublishHistoryEntry | undefined {
  if (!outcome.ok) return undefined;
  const meta = outcome.providerMetadata ?? {};
  return {
    target: outcome.targetId,
    url: outcome.url,
    reachable: outcome.ok === true,
    status: outcome.status,
    projectName: input.projectName,
    publishedAt: clock.nowIso(),
    triggeredBy,
    ...stringField(meta, "owner"),
    ...stringField(meta, "repo"),
    ...stringField(meta, "branch"),
    ...stringField(meta, "commitSha"),
    ...(outcome.basePath !== undefined ? { basePath: outcome.basePath } : {}),
    ...(outcome.deploymentId !== undefined ? { deploymentId: outcome.deploymentId } : {}),
  };
}

/** `{ [key]: value }` when `meta[key]` is a string, else `{}` — host metadata is untyped data. */
function stringField<K extends string>(meta: Readonly<Record<string, unknown>>, key: K): { [P in K]?: string } {
  const value = meta[key];
  return (typeof value === "string" ? { [key]: value } : {}) as { [P in K]?: string };
}

/**
 * Records a settled outcome's history, if it produced one — best-effort, never throws and never
 * changes what the caller reports. A failed history write (a DB error, a full disk) must not turn an
 * otherwise-successful publish into a reported failure: the caller already has the TRUE outcome from
 * {@link publishStaticSite} and returns it regardless: losing "where did we last publish" is a
 * strictly smaller problem than a hard error on this genuinely non-essential bookkeeping step layered
 * on top of a publish that already succeeded.
 *
 * @complexity One registry load, O(f*c) public-field filtering, one history insert.
 */
async function recordHistoryIfPublished(
  deps: StaticPublishDeps,
  historyStore: PublishHistoryStore,
  input: StaticPublishInput,
  outcome: StaticPublishOutcome,
  clock: { nowIso(): string },
  triggeredBy: PublishTrigger
): Promise<void> {
  const entry = toHistoryEntry(input, outcome, clock, triggeredBy);
  if (entry === undefined || !outcome.ok) return;
  const credentialId = outcome.credentialId ?? input.credentialId;
  try {
    // Reuse the descriptor contract, never copy raw config or the resolved credential into history.
    // A registry reload failure must not erase the pre-existing outcome-only history behavior.
    const registry = await deps.loadDeployTargets(input.workspaceId).catch(() => {
      // Loader errors may embed plugin config or credentials; log only the failed operation.
      console.warn("[static-publish] destination registry reload failed; recording outcome only");
      return undefined;
    });
    const target = registry?.get(input.config.target);
    await historyStore.recordSuccess({ workspaceId: input.workspaceId, entry: {
      ...entry,
      ...(credentialId !== undefined ? { credentialId } : {}),
      ...(target !== undefined ? { configFields: publicPublishConfigFields({ descriptor: target.descriptor, config: {
        ...input.config, ...target.module.destinationConfig?.({ providerMetadata: outcome.providerMetadata }),
      } }) } : {}),
    } });
  } catch {
    // Keep the true publish result; database errors can embed secret parameters.
    console.warn("[static-publish] destination history write failed after publish");
  }
}

/**
 * The current/most recent publish run's status, exactly as both callers report it (the HTTP status
 * poll route, and — indirectly, via a thrown/returned refusal — the agent tool).
 *
 * @returns `IDLE_RUN` if no run has ever started in this process.
 * @complexity O(1).
 */
export function getPublishRunSnapshot(): PublishRunSnapshot {
  return publishJobs.latest() ?? IDLE_RUN;
}

/** Capture one accepted/settled publish at the shared run owner. No provider payload leaves here.
 * @complexity O(1) time and space per run. */
function publishEvent(required: { deps: StaticPublishDeps; input: StaticPublishInput; operationId: string; outcome?: "completed" | "errored" }, _optional = {}): void {
  const { deps, input, operationId, outcome } = required;
  if (!input.productEvent) return;
  deps.tracker?.capture({ name: outcome ? "deploy_finished" : "site_publish_started", userId: input.productEvent.userId }, { properties: { operationId, eventId: `publish:${operationId}:${outcome ?? "started"}`, target: input.config.target, source: input.productEvent.source, ...(outcome ? { outcome } : {}) } });
}

/** Scoped job lookup for transport adapters; permission checks belong to the caller.
 * No export bytes, credentials or raw provider error objects enter a snapshot.
 * @complexity O(1) by ID; O(20) for the site's latest retained job.
 */
export function getPublishJobSnapshot({ workspaceId, jobId, requestId }: { workspaceId: string; jobId?: string; requestId?: string }, _options = {}): PublishJobSnapshot<StaticPublishOutcome> | undefined {
  return publishJobs.get({ scopeId: workspaceId, ...(jobId !== undefined ? { jobId } : {}), ...(requestId !== undefined ? { requestId } : {}) });
}

function beginRun(input: StaticPublishInput, clock: { nowIso(): string }, jobId: string): void {
  publishJobs.begin({ jobId, ...(input.requestId ? { requestId: input.requestId } : {}), scopeId: input.workspaceId, target: input.config.target, startedAtIso: clock.nowIso() });
}

function settleWithOutcome(jobId: string, outcome: StaticPublishOutcome, clock: { nowIso(): string }): void {
  if (outcome.ok) publishJobs.progress({ jobId, progress: { url: outcome.url,
    ...(outcome.deploymentId ? { deploymentCreated: true, deploymentId: outcome.deploymentId } : {}) } });
  publishJobs.settle({ jobId, status: outcome.ok ? "completed" : "errored", finishedAtIso: clock.nowIso(), result: outcome });
}

function settleWithError(jobId: string, err: unknown, clock: { nowIso(): string }): void {
  // Unexpected exceptions can embed credentials. Provider errors use the adapter's safe outcome.
  publishJobs.settle({ jobId, status: "errored", finishedAtIso: clock.nowIso(), error: redactSecretShapes({ text: err instanceof Error ? err.message : String(err) }).text });
}

/** Bind provider progress to this job, independently of the initiating tool's signal. */
function jobInput(input: StaticPublishInput, jobId: string): StaticPublishInput {
  return { ...input, onProgress: progress => publishJobs.progress({ jobId, progress }) };
}

/**
 * Starts a new publish run unconditionally and returns the "running" snapshot immediately — the
 * publish itself continues in the background. Used by `publish-site.ts`'s HTTP trigger route, which
 * returns `202` and lets the caller poll {@link getPublishRunSnapshot} for the outcome (same
 * fire-and-forget shape as `export-run.ts`'s `startExportRun`, which this mirrors).
 *
 * Caller contract: the caller must have already confirmed `getPublishRunSnapshot().status !==
 * "running"` in the SAME synchronous stretch of the event loop, with no `await` in between. The
 * shared Jini store also refuses a second running job, so a missed caller guard fails closed rather
 * than starting concurrent exports. This preserves the caller contract (`startExportRun`'s own
 * doc, restated here rather than merely cross-referenced since violating it is exactly the bug this
 * whole file exists to close).
 *
 * @param historyStore - See this file's header ("Publish history") — REQUIRED, no module-level
 *   default; real callers pass `RouteDeps.publishHistoryStore`, tests pass an
 *   `InMemoryPublishHistoryStore`.
 * @param optional.onSettled - Told the run's final status once it settles (the route's product event).
 * @complexity O(1) synchronously; the awaited publish itself is bounded by `publishStaticSite`'s own
 *   complexity note (one export pass plus one provider's fixed poll budget).
 */
export function startPublishRun(deps: StaticPublishDeps, input: StaticPublishInput, clock: { nowIso(): string }, historyStore: PublishHistoryStore,
  optional: { onSettled?: (settled: { status: "completed" | "errored" }) => void; triggeredBy?: PublishTrigger } = {}): PublishRunSnapshot {
  const operationId = input.idGen.newId();
  beginRun(input, clock, operationId);
  publishEvent({ deps, input, operationId });

  void publishStaticSite(deps, jobInput(input, operationId))
    .then(async (outcome) => {
      // Record first: callers that refresh destinations once the snapshot completes must see this run.
      await recordHistoryIfPublished(deps, historyStore, input, outcome, clock, optional.triggeredBy ?? "admin_ui");
      settleWithOutcome(operationId, outcome, clock);
    })
    .catch((err: unknown) => settleWithError(operationId, err, clock))
    .finally(() => {
      const status = publishJobs.get({ scopeId: input.workspaceId, jobId: operationId })?.status === "completed" ? "completed" : "errored";
      publishEvent({ deps, input, operationId, outcome: status });
      optional.onSettled?.({ status });
    });

  return getPublishRunSnapshot();
}

// Generic, Jini candidate: tracked in .cloud-coord/round2-progress.md#jini-extraction-backlog.
import { parse, serialize, type DefaultTreeAdapterMap } from "parse5";
import { htmlToText, stripActiveHtml } from "@jini-ai/platform/web";

/**
 * @file The pure half of email templates: `{{field}}` fill-ins, the template's own declarations
 * (subject and fields, read out of its HTML), and the two renders — the admin PREVIEW, which keeps
 * the template's scripts because it is shown in the Pages preview iframe's sandbox, and the SEND
 * render, which is static HTML because mail clients strip script anyway and a message that relied
 * on it would arrive broken.
 *
 * Everything a template declares lives in its HTML, not in extra columns: a template is an
 * `"html"`-format row in the Pages store (see `operations.ts`), and that store's single body is the
 * one source of truth an agent edits with the same full-document writes it uses for a Page.
 *
 * - Subject: the document's `<title>` (it may itself contain `{{field}}`s).
 * - Fields: `<meta name="email-fields" content="name=Ada, orderId">` — comma-separated names, each
 *   optionally `=sample` (the value a preview shows when the caller gives none).
 */

type ParentNode = DefaultTreeAdapterMap["parentNode"];
type ChildNode = DefaultTreeAdapterMap["childNode"];
type Element = DefaultTreeAdapterMap["element"];

/** The `<meta name>` a template declares its fill-in fields with. */
export const EMAIL_FIELDS_META_NAME = "email-fields";

/** `{{ name }}` — a field name is an identifier, optionally dotted or dashed. */
const PLACEHOLDER = /\{\{\s*([A-Za-z_][A-Za-z0-9_.-]*)\s*\}\}/g;
const FIELD_NAME = /^[A-Za-z_][A-Za-z0-9_.-]*$/;
const HTML_NAMESPACE = "http://www.w3.org/1999/xhtml";

/** Tags a sent email never carries: embedded documents and plugins, on top of `stripActiveHtml`'s. */
const SEND_STRIPPED_TAGS = new Set(["iframe", "object", "embed", "frame", "frameset", "applet", "base", "form", "link"]);
/** Script-bearing URL schemes; tested after removing the whitespace/control characters a browser ignores. */
const ACTIVE_URL = /^(?:javascript|vbscript):/i;

export interface EmailTemplateField {
  name: string;
  /** Shown by the preview when the caller gives no value for this field. */
  sample?: string;
}

export interface EmailTemplateDeclarations {
  /** The raw `<title>` text, placeholders unfilled; `""` when the template has none. */
  subject: string;
  fields: EmailTemplateField[];
}

export type EmailFieldValues = Readonly<Record<string, string>>;

export interface FilledText {
  text: string;
  /** Placeholders the values did not cover, in first-use order; each was rendered empty. */
  missingFields: string[];
}

/** The `{{field}}` names a string uses, de-duplicated in first-use order. */
export function placeholdersIn({ text }: { text: string }, _optional: Record<string, never> = {}): string[] {
  // PLACEHOLDER requires this capture; narrow it explicitly because indexed reads may be undefined.
  const names = [...text.matchAll(PLACEHOLDER)].map((match) => match[1]).filter((name): name is string => name !== undefined);
  return [...new Set(names)];
}

/** Escapes a value for HTML text AND quoted-attribute context. */
export function escapeHtml({ value }: { value: string }, _optional: Record<string, never> = {}): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

/**
 * Replaces every `{{field}}` with its value. An unknown field renders empty — never the literal
 * braces a recipient would see — and is reported so the caller can refuse or warn.
 * @param required.escape - Applied to every value: {@link escapeHtml} for HTML, identity for a subject.
 * @complexity O(n) in the text length.
 */
export function fillPlaceholders(
  { text, values, escape: escapeValue }: { text: string; values: EmailFieldValues; escape: (value: string) => string },
  _optional: Record<string, never> = {},
): FilledText {
  const missing = new Set<string>();
  const filled = text.replace(PLACEHOLDER, (_match, name: string) => {
    if (!Object.hasOwn(values, name)) {
      missing.add(name);
      return "";
    }
    // Own keys contain strings by contract; the default also makes the indexed read explicit.
    return escapeValue(values[name] ?? "");
  });
  return { text: filled, missingFields: [...missing] };
}

/** One `name` or `name=sample` entry; `null` for a malformed name, which is ignored. */
function parseFieldEntry({ entry }: { entry: string }, _options: Record<string, never> = {}): EmailTemplateField | null {
  const separator = entry.indexOf("=");
  const name = (separator === -1 ? entry : entry.slice(0, separator)).trim();
  if (!FIELD_NAME.test(name)) return null;
  if (separator === -1) return { name };
  return { name, sample: entry.slice(separator + 1).trim() };
}

/** The declared fields from a `content` attribute, first declaration of a name winning. */
export function parseFieldDeclarations({ content }: { content: string }, _optional: Record<string, never> = {}): EmailTemplateField[] {
  const byName = new Map<string, EmailTemplateField>();
  for (const entry of content.split(",")) {
    const field = parseFieldEntry({ entry: entry });
    if (field && !byName.has(field.name)) byName.set(field.name, field);
  }
  return [...byName.values()];
}

/** Writes a field list back into the `content` form {@link parseFieldDeclarations} reads. */
export function formatFieldDeclarations({ fields }: { fields: readonly EmailTemplateField[] }, _optional: Record<string, never> = {}): string {
  return fields.map((field) => (field.sample === undefined ? field.name : `${field.name}=${field.sample}`)).join(", ");
}

function isElement(node: ChildNode | ParentNode): node is Element {
  return "tagName" in node;
}

function attribute({ element, name }: { element: Element; name: string }, _options: Record<string, never> = {}): string | undefined {
  return element.attrs.find((attr) => attr.name === name)?.value;
}

/** Every element under `root`, in document order (so "the first `<title>`" means the first one written). */
function* elementsIn(root: ParentNode, _options: Record<string, never> = {}): Generator<Element> {
  const pending: ParentNode[] = [root];
  while (pending.length > 0) {
    const node = pending.pop();
    // Array length checks do not narrow pop() or indexed reads under the desktop config.
    if (node === undefined) continue;
    if (isElement(node)) yield node;
    queueChildParents({ node, pending });
  }
}

/** Reverse insertion preserves document order on the traversal's stack. */
function queueChildParents({ node, pending }: { node: ParentNode; pending: ParentNode[] }, _options = {}): void {
  for (let i = node.childNodes.length - 1; i >= 0; i--) {
    const child = node.childNodes[i];
    if (child !== undefined && "childNodes" in child) pending.push(child);
  }
}

function textOf(element: Element, _options: Record<string, never> = {}): string {
  return element.childNodes.map((child) => ("value" in child && child.nodeName === "#text" ? child.value : "")).join("");
}

function isFieldsMeta(element: Element, _options: Record<string, never> = {}): boolean {
  return element.tagName === "meta" && attribute({ element: element, name: "name" })?.toLowerCase() === EMAIL_FIELDS_META_NAME;
}

/**
 * Reads a template's subject (`<title>`) and declared fields (`<meta name="email-fields">`).
 * @complexity O(nodes).
 */
export function readTemplateDeclarations({ html }: { html: string }, _optional: Record<string, never> = {}): EmailTemplateDeclarations {
  let subject: string | undefined;
  let fields: EmailTemplateField[] = [];
  let fieldsDeclared = false;
  for (const element of elementsIn(parse(html))) {
    // HTML namespace only: an inline `<svg><title>` is an image's tooltip, not the subject.
    if (element.tagName === "title" && element.namespaceURI === HTML_NAMESPACE && subject === undefined) subject = textOf(element).trim();
    if (isFieldsMeta(element) && !fieldsDeclared) {
      fieldsDeclared = true;
      fields = parseFieldDeclarations({ content: attribute({ element: element, name: "content" }) ?? "" });
    }
  }
  return { subject: subject ?? "", fields };
}

/** Placeholders used in the HTML (subject included) that the template never declared. */
export function undeclaredFieldsIn({ html, declarations }: { html: string; declarations: EmailTemplateDeclarations }, _optional: Record<string, never> = {}): string[] {
  const declared = new Set(declarations.fields.map((field) => field.name));
  return placeholdersIn({ text: html }).filter((name) => !declared.has(name));
}

/** True when an attribute value would run script once a browser normalizes it as a URL. Tested on
 * every attribute, not only `href`/`src`, the same breadth `stripActiveHtml` applies. */
function isActiveUrl({ value }: { value: string }, _options: Record<string, never> = {}): boolean {
  // Browsers drop ASCII tab/newline anywhere in a URL and leading C0 controls/space, so
  // `java\nscript:` is still script; `stripActiveHtml`'s own test only trims leading whitespace.
  // eslint-disable-next-line no-control-regex
  const normalized = value.replace(/[\u0000- ]/g, "");
  return ACTIVE_URL.test(normalized) || (/^data:/i.test(normalized) && !/^data:image\/[^;,]+[;,]/i.test(normalized));
}

/** Static mail excludes navigation instructions, form submissions and external stylesheets. */
function stripMailElement({ child }: { child: ChildNode }, _optional: Record<string, never> = {}): boolean {
  if (!isElement(child)) return false;
  if (SEND_STRIPPED_TAGS.has(child.tagName) || isFieldsMeta(child)) return true;
  return child.tagName === "meta" && attribute({ element: child, name: "http-equiv" }) !== undefined;
}

/** Second, email-specific pass after `stripActiveHtml`: embeds, obfuscated script URLs, the fields meta. */
function stripForMail(root: ParentNode, _options: Record<string, never> = {}): void {
  for (const node of elementsIn(root)) {
    node.childNodes = node.childNodes.filter((child) => !stripMailElement({ child }));
    node.attrs = node.attrs.filter((attr) => !isActiveUrl({ value: attr.value }));
  }
}

/**
 * The static HTML a mail client receives: `<script>`/`<noscript>`/`<template>`, comments, inline
 * `on*` handlers and `javascript:` URLs removed (the shared `stripActiveHtml` policy), then
 * `<iframe>`/`<object>`/`<embed>` (and their legacy kin), obfuscated script URLs and the template's
 * own field declarations. Navigation/form/link elements and non-image data URLs are removed.
 * Inline styles and classes survive: email layout depends on them.
 *
 * Known cost: comments are removed, so Outlook `<!--[if mso]>` conditional blocks do not survive.
 * @complexity O(nodes), two parses.
 */
export function sanitizeEmailHtml({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const document = parse(stripActiveHtml({ html }));
  stripForMail(document);
  return serialize(document);
}

/** A visible ` (url)` after a link whose text is not already its URL, so the text part keeps links. */
function annotateLinks(root: ParentNode, _options: Record<string, never> = {}): void {
  for (const element of elementsIn(root)) {
    const href = element.tagName === "a" ? attribute({ element: element, name: "href" })?.trim() : undefined;
    if (!href || !/^(?:https?:|mailto:)/i.test(href) || textOf(element).trim() === href) continue;
    element.childNodes.push({ nodeName: "#text", value: ` (${href.replace(/^mailto:/i, "")})`, parentNode: element } as ChildNode);
  }
}

/**
 * The plain-text alternative: the shared `htmlToText` (one line per block; head, scripts and styles
 * omitted), with each link's URL written after its text so a text-only reader can still follow it.
 * @complexity O(nodes).
 */
export function emailHtmlToText({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const document = parse(html);
  annotateLinks(document);
  return htmlToText({ html: serialize(document) });
}

/** A subject is one header line: fill raw (it is not HTML) and fold any line break a value carried. */
function renderSubject({ subject, values }: { subject: string; values: EmailFieldValues }, _options: Record<string, never> = {}): FilledText {
  const filled = fillPlaceholders({ text: subject, values, escape: (value) => value });
  return { text: filled.text.replace(/[\r\n]+/g, " ").trim(), missingFields: filled.missingFields };
}

export interface RenderedEmail {
  subject: string;
  html: string;
  /** Placeholders no value covered, subject and body together; each rendered empty. */
  missingFields: string[];
}

function renderWith({ html, values }: { html: string; values: EmailFieldValues }, _options: Record<string, never> = {}): RenderedEmail {
  const declarations = readTemplateDeclarations({ html });
  const subject = renderSubject({ subject: declarations.subject, values: values });
  const body = fillPlaceholders({ text: html, values, escape: (value) => escapeHtml({ value }) });
  return { subject: subject.text, html: body.text, missingFields: [...new Set([...subject.missingFields, ...body.missingFields])] };
}

/** The values a preview renders with: declared samples, overridden by whatever the caller gave. */
export function previewValues(
  { declarations, values }: { declarations: EmailTemplateDeclarations; values: EmailFieldValues },
  _optional: Record<string, never> = {},
): Record<string, string> {
  const samples = declarations.fields.flatMap((field) => (field.sample === undefined ? [] : [[field.name, field.sample] as const]));
  return { ...Object.fromEntries(samples), ...values };
}

/**
 * The admin preview. Scripts are KEPT — the preview is the Pages preview iframe, sandboxed without
 * `allow-same-origin`, so they run in an opaque origin — and `scriptsStripped: false` says so.
 * @complexity O(n) in the template length.
 */
export function renderEmailPreview({ html, values }: { html: string; values: EmailFieldValues }, _optional: Record<string, never> = {}): RenderedEmail {
  const declarations = readTemplateDeclarations({ html });
  return renderWith({ html: html, values: previewValues({ declarations, values }) });
}

export interface SendableEmail extends RenderedEmail {
  /** The plain-text alternative, derived from the sanitized HTML. */
  text: string;
}

/**
 * Template + values -> the `subject`/`html`/`text` an `OutboundEmail` carries. Values are filled
 * BEFORE sanitizing, so a value that smuggles a `javascript:` URL into an `href="{{url}}"` is
 * removed with everything else. Samples are never used: a sent email shows only real values.
 * @complexity O(n) in the template length.
 */
export function renderEmailForSend({ html, values }: { html: string; values: EmailFieldValues }, _optional: Record<string, never> = {}): SendableEmail {
  const rendered = renderWith({ html: html, values: values });
  const safeHtml = sanitizeEmailHtml({ html: rendered.html });
  return { subject: rendered.subject, html: safeHtml, text: emailHtmlToText({ html: safeHtml }), missingFields: rendered.missingFields };
}

/** The starter body a template is born with when its creator gives no HTML. */
export function emailTemplateSkeleton(
  { subject, fields }: { subject: string; fields: readonly EmailTemplateField[] },
  _optional: Record<string, never> = {},
): string {
  const meta = fields.length > 0 ? `\n<meta name="${EMAIL_FIELDS_META_NAME}" content="${escapeHtml({ value: formatFieldDeclarations({ fields }) })}">` : "";
  // Guard the first field itself so an empty list keeps its plain greeting.
  const firstField = fields[0];
  const greeting = firstField === undefined ? "Hello," : `Hello {{${firstField.name}}},`;
  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">${meta}
<title>${escapeHtml({ value: subject })}</title>
</head>
<body style="margin:0;padding:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;color:#18181b;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;">
<tr><td align="center" style="padding:24px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:8px;">
<tr><td style="padding:32px;font-size:16px;line-height:1.5;">
<p>${greeting}</p>
<p></p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>
`;
}
